async function whatsappCustomerServiceWindowOpen(tenantId, phone, now) {
  if (!SUPABASE_ENABLED || !SUPABASE_TENANT_COLUMNS_ENABLED) return false;
  const userId = normalizeConversationUserId(phone);
  const cleanTenant = canonicalRuntimeTenantId(tenantId);
  if (!userId || !cleanTenant) return false;
  try {
    const response = await axios.get(SUPABASE_URL + "/rest/v1/" + SUPABASE_TABLE, {
      params: {
        select: "ts",
        tenant_id: "eq." + cleanTenant,
        user_id: "eq." + userId,
        channel: "eq.whatsapp",
        order: "ts.desc",
        limit: 1
      },
      headers: SB_HEADERS,
      timeout: 8000
    });
    const lastInboundAt = Date.parse(response.data && response.data[0] && response.data[0].ts || "");
    const current = new Date(now || Date.now()).getTime();
    return Number.isFinite(lastInboundAt) && current >= lastInboundAt && current - lastInboundAt < 24 * 60 * 60 * 1000;
  } catch (error) {
    log("warn", "appointment_customer_window_lookup_failed", {
      tenant_id: cleanTenant,
      error: cleanRuntimeText(error && error.message, 200)
    });
    return false;
  }
}

async function appointmentsStorageReady(force) {
  if (APPOINTMENT_STORAGE_TEST_READY) {
    appointmentStorageHealth.checked_at = Date.now();
    appointmentStorageHealth.ready = true;
    appointmentStorageHealth.error = "";
    return true;
  }
  if (!SUPABASE_APPOINTMENTS_ENABLED) return false;
  const now = Date.now();
  if (!force && appointmentStorageHealth.checked_at && now - appointmentStorageHealth.checked_at < 30000) {
    return appointmentStorageHealth.ready;
  }
  try {
    const response = await axios.get(SUPABASE_URL + "/rest/v1/" + SUPABASE_APPOINTMENTS_TABLE, {
      params: { select: "id", limit: 1 },
      headers: SB_HEADERS,
      timeout: 8000
    });
    appointmentStorageHealth.checked_at = now;
    appointmentStorageHealth.ready = response.status === 200;
    appointmentStorageHealth.error = "";
  } catch (error) {
    appointmentStorageHealth.checked_at = now;
    appointmentStorageHealth.ready = false;
    appointmentStorageHealth.error = String(
      error && error.response && error.response.data && error.response.data.message ||
      error && error.message ||
      "appointments_storage_unavailable"
    ).slice(0, 240);
  }
  return appointmentStorageHealth.ready;
}

function appointmentReminderMemoryKey(row) {
  return cleanTenantId(row && row.tenant_id) + ":" + String(row && (row.id || row.reminder_key) || "");
}

function appointmentReminderDbPayload(row) {
  const normalized = normalizeReminder(row);
  const metadata = Object.assign({}, row && row.metadata || {}, {
    customer_name: cleanRuntimeText(row && row.customer_name, 160),
    service: cleanRuntimeText(row && (row.service || row.consultation_reason), 500),
    appointment_starts_at: row && row.appointment_starts_at || null,
    reminder_kind: cleanRuntimeText(row && row.reminder_kind, 80),
    aftercare_outcome: cleanRuntimeText(row && row.aftercare_outcome, 40),
    aftercare_message: cleanRuntimeText(row && row.aftercare_message, 2000)
  });
  const payload = {
    tenant_id: normalized.tenant_id,
    appointment_id: normalized.appointment_id,
    reminder_key: cleanRuntimeText(row && (row.dedupe_key || row.reminder_key || row.id), 500),
    conversation_id: normalized.conversation_id || null,
    channel: normalized.channel,
    offset_minutes: normalized.offset_minutes,
    scheduled_for: normalized.scheduled_for,
    status: normalized.status,
    attempts: normalized.attempts,
    provider_message_id: cleanRuntimeText(row && row.provider_message_id, 500) || null,
    sent_at: row && row.sent_at || null,
    delivered_at: row && row.delivered_at || null,
    read_at: row && row.read_at || null,
    confirmed_at: row && row.confirmed_at || null,
    last_action: cleanRuntimeText(row && row.last_action, 80) || null,
    last_action_by: cleanRuntimeText(row && row.last_action_by, 200) || null,
    last_action_at: row && row.last_action_at || null,
    last_error: cleanRuntimeText(row && row.last_error, 1000) || null,
    metadata,
    updated_at: row && row.updated_at || new Date().toISOString()
  };
  return payload;
}

function appointmentReminderFromStored(row) {
  const metadata = row && row.metadata || {};
  return normalizeReminder(Object.assign({}, row, {
    customer_name: metadata.customer_name || "",
    service: metadata.service || "",
    appointment_starts_at: metadata.appointment_starts_at || null,
    reminder_kind: metadata.reminder_kind || "",
    aftercare_outcome: metadata.aftercare_outcome || "",
    aftercare_message: metadata.aftercare_message || "",
    dedupe_key: row && row.reminder_key
  }));
}

async function loadAppointmentRemindersForTenant(tenantId) {
  const cleanTenant = cleanTenantId(tenantId);
  if (!cleanTenant || !APPOINTMENT_REMINDERS_V1_ENABLED) return [];
  if (SUPABASE_APPOINTMENTS_ENABLED) {
    try {
      const response = await axios.get(SUPABASE_URL + "/rest/v1/" + SUPABASE_APPOINTMENT_REMINDERS_TABLE, {
        params: { select: "*", tenant_id: "eq." + cleanTenant, order: "scheduled_for.asc", limit: 1000 },
        headers: SB_HEADERS,
        timeout: 8000
      });
      return (response.data || []).map(appointmentReminderFromStored);
    } catch (error) {
      log("warn", "appointment_reminders_load_failed", {
        tenant_id: cleanTenant,
        error: cleanRuntimeText(error && error.message, 240)
      });
    }
  }
  return Array.from(appointmentReminderMemory.values()).filter(function (row) {
    return row.tenant_id === cleanTenant;
  });
}

async function persistAppointmentReminders(rows) {
  const records = (rows || []).map(function (row) {
    const normalized = normalizeReminder(row);
    appointmentReminderMemory.set(appointmentReminderMemoryKey(normalized), normalized);
    return appointmentReminderDbPayload(Object.assign({}, row, normalized));
  }).filter(function (row) { return row.tenant_id && row.appointment_id && row.reminder_key; });
  if (!records.length || !SUPABASE_APPOINTMENTS_ENABLED) return records;
  await axios.post(
    SUPABASE_URL + "/rest/v1/" + SUPABASE_APPOINTMENT_REMINDERS_TABLE + "?on_conflict=tenant_id,reminder_key",
    records,
    { headers: Object.assign({ Prefer: "resolution=merge-duplicates,return=minimal" }, SB_HEADERS), timeout: 8000 }
  );
  return records;
}

async function recordAppointmentReminderDeliveryStatus(tenantId, providerMessageId, status) {
  const messageId = cleanRuntimeText(providerMessageId, 500);
  const state = cleanRuntimeText(status, 40).toLowerCase();
  if (!messageId || !["sent", "delivered", "read", "failed"].includes(state)) return false;
  const rows = await loadAppointmentRemindersForTenant(tenantId);
  const reminder = rows.find(function (row) { return row.provider_message_id === messageId; });
  if (!reminder) return false;
  const now = new Date().toISOString();
  const update = Object.assign({}, reminder, {
    status: state,
    delivered_at: state === "delivered" || state === "read" ? (reminder.delivered_at || now) : reminder.delivered_at,
    read_at: state === "read" ? now : reminder.read_at,
    last_error: state === "failed" ? "provider_delivery_failed" : null,
    updated_at: now
  });
  await persistAppointmentReminders([update]);
  return true;
}

function appointmentReminderReplyConfirms(message) {
  const normalized = String(message || "").normalize("NFD").replace(/[\u0300-\u036f]/g, "")
    .toLowerCase().replace(/[^a-z0-9\s]/g, " ").replace(/\s+/g, " ").trim();
  return /^(si( confirmo)?|confirmo|confirmado|confirmada|de acuerdo|ok|okay|listo|claro|ahi estare|voy a asistir)$/.test(normalized);
}

async function recordAppointmentReminderCustomerReply(tenantId, conversationId, message) {
  const cleanTenant = cleanTenantId(tenantId);
  const cleanConversation = normalizeConversationUserId(conversationId);
  if (!cleanTenant || !cleanConversation || !APPOINTMENT_REMINDERS_V1_ENABLED) return false;
  const rows = await loadAppointmentRemindersForTenant(cleanTenant);
  const candidates = rows.filter(function (row) {
    return row.conversation_id === cleanConversation && ["sent", "delivered", "read"].includes(row.status);
  }).sort(function (left, right) {
    return String(right.sent_at || right.updated_at || "").localeCompare(String(left.sent_at || left.updated_at || ""));
  });
  if (!candidates.length) return false;
  const now = new Date().toISOString();
  const target = candidates[0];
  const confirmed = appointmentReminderReplyConfirms(message);
  const updates = rows.filter(function (row) {
    return row.appointment_id === target.appointment_id &&
      (row.id === target.id || confirmed && ["scheduled", "paused", "retrying", "failed"].includes(row.status));
  }).map(function (row) {
    if (row.id === target.id) {
      return Object.assign({}, row, {
        status: confirmed ? "confirmed" : "read",
        read_at: row.read_at || now,
        confirmed_at: confirmed ? now : row.confirmed_at,
        last_action: confirmed ? "customer_confirmed" : "customer_replied",
        last_action_by: "customer",
        last_action_at: now,
        updated_at: now
      });
    }
    return Object.assign({}, row, {
      status: "cancelled",
      last_action: "appointment_confirmed",
      last_action_by: "customer",
      last_action_at: now,
      updated_at: now
    });
  });
  await persistAppointmentReminders(updates);
  return confirmed ? "confirmed" : "replied";
}

async function refreshAppointmentRemindersForTenant(tenantId, settings, appointments) {
  if (!APPOINTMENT_REMINDERS_V1_ENABLED) return [];
  const existing = await loadAppointmentRemindersForTenant(tenantId);
  const byAppointment = new Map();
  existing.forEach(function (row) {
    const key = String(row.appointment_id || "");
    if (!byAppointment.has(key)) byAppointment.set(key, []);
    byAppointment.get(key).push(row);
  });
  const materialized = [];
  (appointments || []).forEach(function (appointment) {
    const generated = materializeAppointmentReminders(
      appointment,
      settings,
      byAppointment.get(String(appointment.appointment_id || appointment.conversation_id)) || [],
      { now: new Date().toISOString() }
    );
    generated.forEach(function (row) {
      materialized.push(Object.assign({}, row, {
        customer_name: appointment.customer_name,
        service: appointment.consultation_reason,
        appointment_starts_at: appointment.starts_at
      }));
    });
  });
  await persistAppointmentReminders(materialized);
  return loadAppointmentRemindersForTenant(tenantId);
}

async function syncAppointmentReminderSchedule(tenantId, appointment) {
  if (!APPOINTMENT_REMINDERS_V1_ENABLED || !appointment) return [];
  const onboarding = await loadClientOnboarding(false, tenantId);
  const settings = appointmentSettingsFromOnboarding(onboarding);
  const existing = await loadAppointmentRemindersForTenant(tenantId);
  const generated = materializeAppointmentReminders(appointment, settings, existing, {
    now: new Date().toISOString()
  }).map(function (row) {
    return Object.assign({}, row, {
      customer_name: appointment.customer_name,
      service: appointment.consultation_reason,
      appointment_starts_at: appointment.starts_at
    });
  });
  try {
    await persistAppointmentReminders(generated);
    return generated;
  } catch (error) {
    // A reminder is supplementary to the booking. Its storage must never make
    // an already-created appointment fail for the customer or block the bot.
    log("warn", "appointment_reminder_schedule_persist_failed", {
      tenant_id: cleanTenantId(tenantId),
      appointment_id_suffix: String(appointment && (appointment.appointment_id || appointment.conversation_id) || "").slice(-12),
      error: cleanRuntimeText(error && error.message, 240) || "appointment_reminder_storage_unavailable"
    });
    return [];
  }
}

function appointmentReminderMessage(row, appointment, configuration) {
  const name = cleanRuntimeText(row && row.customer_name || appointment && appointment.customer_name, 80);
  const service = cleanRuntimeText(row && row.service || appointment && appointment.consultation_reason || "tu cita", 180);
  if (String(row && row.reminder_kind || "").indexOf("appointment_aftercare") === 0) {
    const business = cleanRuntimeText(configuration && configuration.business_name, 160) || "tu negocio";
    return cleanRuntimeText(row && row.aftercare_message, 2000)
      .replace(/\{nombre\}/gi, name || "Cliente")
      .replace(/\{servicio\}/gi, service || "tu cita")
      .replace(/\{negocio\}/gi, business);
  }
  const startsAt = new Date(appointment && appointment.starts_at || row && row.appointment_starts_at);
  const when = Number.isFinite(startsAt.getTime())
    ? startsAt.toLocaleString("es-CO", { timeZone: "America/Bogota", weekday: "long", day: "numeric", month: "long", hour: "numeric", minute: "2-digit" })
    : "el horario acordado";
  const access = appointment && appointment.appointment_modality === "virtual"
    ? (safeExternalHttpsUrl(appointment.virtual_meeting_link)
      ? " Enlace de acceso: " + safeExternalHttpsUrl(appointment.virtual_meeting_link)
      : " El enlace de acceso te llegará por separado.")
    : appointment && appointment.appointment_modality === "in_person" && cleanRuntimeText(appointment.physical_address, 1000)
      ? " Lugar: " + cleanRuntimeText(appointment.physical_address, 1000)
      : "";
  return "Hola" + (name ? " " + name.split(/\s+/)[0] : "") + " 👋 Te recordamos " + service + " para " + when + "." + access + " Responde a este mensaje para confirmar o pedir un cambio.";
}

async function deliverAppointmentReminder(row, appointment) {
  const recipient = cleanRuntimeText(row && row.conversation_id || appointment && appointment.customer_conversation_id, 500) ||
    (row && row.channel === "whatsapp" ? cleanRuntimeText(appointment && appointment.customer_phone, 80) : "");
  if (!recipient) throw new Error("appointment_reminder_recipient_missing");
  const isAftercare = String(row && row.reminder_kind || "").indexOf("appointment_aftercare") === 0;
  const configuration = row.channel === "whatsapp" ? await appointmentReminderConfiguration(row.tenant_id) : null;
  const message = appointmentReminderMessage(row, appointment, configuration);
  if (row.channel === "whatsapp") {
    if (await whatsappCustomerServiceWindowOpen(row.tenant_id, recipient)) {
      const deliveryResult = {};
      const sent = await sendText(recipient, message, {
        tenant_id: row.tenant_id,
        human_agent: false,
        delivery_result: deliveryResult
      });
      if (!sent) throw new Error("appointment_reminder_whatsapp_text_failed");
      return deliveryResult.provider_message_id || "";
    }
    if (isAftercare) {
      // A tenant-authored free-form follow-up cannot be substituted into the
      // approved appointment template without changing its meaning. Fail
      // closed and surface the existing handoff instead of sending misleading
      // content outside Meta's customer-service window.
      throw new Error("appointment_aftercare_outside_customer_service_window");
    }
    const when = appointmentDateTime(appointment && appointment.starts_at, configuration.timezone);
    const result = await metaMessageHub.request({
      tenant_id: row.tenant_id,
      channel: "whatsapp",
      source: "appointment",
      use_case: "appointment_reminder",
      recipient,
      parameters: {
        customer_name: cleanRuntimeText(row.customer_name || appointment && appointment.customer_name, 80) || "Cliente",
        business_name: configuration.business_name || "Nextfor",
        appointment_date: when.date,
        appointment_time: when.time
      },
      idempotency_key: ["appointment-reminder", row.id || row.reminder_key, row.due_at || row.scheduled_for].join(":")
    });
    if (!result || result.status !== "accepted") {
      throw new Error("appointment_reminder_whatsapp_failed");
    }
    return result.provider_message_id || "";
  }
  const sent = await sendText(recipient, message, { tenant_id: row.tenant_id, human_agent: false });
  if (!sent) throw new Error("appointment_reminder_text_failed");
  return "";
}

async function sendAppointmentReminderRecord(row, actor) {
  const tenantId = cleanTenantId(row && row.tenant_id);
  await hydrateAppointmentsForTenant(tenantId);
  const appointment = appointmentRegistry.get(tenantId, row && row.appointment_id);
  if (!appointment) throw new AppointmentOperationsError("appointment_not_found", 404);
  if (!APPOINTMENT_REMINDER_SENDS_ENABLED) {
    throw new AppointmentOperationsError("appointment_reminder_sends_disabled", 503);
  }
  const onboarding = await loadClientOnboarding(false, tenantId);
  const policy = appointmentSettingsFromOnboarding(onboarding).reminder_policy;
  const attempts = row.status === "sending" ? Number(row.attempts) || 1 : (Number(row.attempts) || 0) + 1;
  const sending = Object.assign({}, row, {
    status: "sending",
    attempts,
    last_action: "sending",
    last_action_by: actor,
    last_action_at: new Date().toISOString(),
    updated_at: new Date().toISOString()
  });
  await persistAppointmentReminders([sending]);
  try {
    const providerMessageId = await deliverAppointmentReminder(sending, appointment);
    const sent = Object.assign({}, sending, {
      status: "sent",
      provider_message_id: providerMessageId || null,
      sent_at: new Date().toISOString(),
      last_action: "sent",
      last_action_by: actor,
      last_action_at: new Date().toISOString(),
      last_error: null,
      updated_at: new Date().toISOString()
    });
    await persistAppointmentReminders([sent]);
    return sent;
  } catch (error) {
    const exhausted = attempts >= (Number(policy.max_attempts) || 2);
    const failed = Object.assign({}, sending, {
      status: exhausted ? "no_response" : "retrying",
      scheduled_for: exhausted ? sending.scheduled_for : new Date(Date.now() + (Number(policy.retry_after_minutes) || 120) * 60000).toISOString(),
      last_error: cleanRuntimeText(error && error.message, 1000),
      last_action: "send_failed",
      last_action_by: actor,
      last_action_at: new Date().toISOString(),
      updated_at: new Date().toISOString()
    });
    await persistAppointmentReminders([failed]);
    if (failed.status === "no_response" && policy.handoff_on_no_response !== false && failed.conversation_id) {
      await customerNotificationService.createHandoff({
        id: "appointment-reminder:" + failed.id,
        tenant_id: tenantId,
        conversation_id: failed.conversation_id,
        channel: failed.channel === "whatsapp" ? "whatsapp" : conversationChannel(failed.conversation_id),
        customer_label: failed.customer_name || appointment.customer_name || "Un cliente",
        reason: "appointment_reminder_no_response",
        title: "Una cita necesita tu ayuda",
        message: "No pudimos confirmar esta cita automáticamente. Abre la conversación para continuar."
      });
    }
    throw error;
  }
}

async function processDueAppointmentReminders() {
  if (!APPOINTMENT_REMINDER_SENDS_ENABLED || !SUPABASE_APPOINTMENTS_ENABLED || appointmentReminderProcessing) return;
  appointmentReminderProcessing = true;
  try {
    const response = await axios.post(
      SUPABASE_URL + "/rest/v1/rpc/claim_due_appointment_reminders",
      { p_limit: 20, p_worker_id: "nextfor-" + process.pid },
      { headers: SB_HEADERS, timeout: 8000 }
    );
    for (const stored of response.data || []) {
      const row = appointmentReminderFromStored(stored);
      try { await sendAppointmentReminderRecord(row, "appointment-reminder-worker"); }
      catch (error) {
        log("warn", "appointment_reminder_send_failed", {
          tenant_id: row.tenant_id,
          reminder_id: row.id,
          error: cleanRuntimeText(error && error.message, 240)
        });
      }
    }
  } catch (error) {
    log("warn", "appointment_reminder_worker_failed", { error: cleanRuntimeText(error && error.message, 240) });
  } finally {
    appointmentReminderProcessing = false;
  }
}

if (APPOINTMENT_REMINDERS_V1_ENABLED) {
  const appointmentReminderTimer = setInterval(processDueAppointmentReminders, 60000);
  if (appointmentReminderTimer.unref) appointmentReminderTimer.unref();
  setTimeout(processDueAppointmentReminders, 2000);
}

async function recoverUpcomingAppointmentReminderSchedules() {
  if (!APPOINTMENT_REMINDERS_V1_ENABLED || !SUPABASE_APPOINTMENTS_ENABLED) return;
  try {
    const appointments = await loadUpcomingAppointmentsForReminderWorker();
    let recovered = 0;
    let failed = 0;
    for (const appointment of appointments) {
      try {
        await syncAppointmentReminderSchedule(appointment.tenant_id, appointment);
        recovered += 1;
      } catch (error) {
        failed += 1;
        const response = error && error.response && error.response.data || {};
        log("warn", "appointment_reminder_schedule_recovery_item_failed", {
          tenant_id: cleanTenantId(appointment && appointment.tenant_id),
          appointment_id_suffix: String(appointment && (appointment.appointment_id || appointment.conversation_id) || "").slice(-12),
          code: cleanRuntimeText(response.code, 80) || null,
          error: cleanRuntimeText(response.message || error && error.message, 240)
        });
      }
    }
    await processDueAppointmentReminders();
    if (appointments.length) {
      log(failed ? "warn" : "info", "appointment_reminder_schedules_recovered", {
        inspected: appointments.length,
        recovered,
        failed
      });
    }
  } catch (error) {
    log("warn", "appointment_reminder_schedule_recovery_failed", {
      error: cleanRuntimeText(error && error.message, 240)
    });
  }
}

if (APPOINTMENT_REMINDERS_V1_ENABLED && SUPABASE_APPOINTMENTS_ENABLED) {
  setTimeout(recoverUpcomingAppointmentReminderSchedules, 4000);
}

async function supabaseInsert(rec) {
  if (!SUPABASE_ENABLED) return;
  try {
    const payload = {
      ts: rec.ts, user_id: rec.userId, user_message: encryptStoredText(rec.userMessage, DATA_ENCRYPTION_KEY), bot_reply: encryptStoredText(rec.botReply, DATA_ENCRYPTION_KEY),
      tools: rec.tools, zero_result_queries: rec.zeroResultQueries, handoff: rec.handoff,
      rating: rec.rating, num_tools: rec.numTools, status: rec.status
    };
    if (SUPABASE_TENANT_COLUMNS_ENABLED) {
      payload.tenant_id = rec.tenantId || DEFAULT_TENANT_ID;
      payload.phone_number_id = rec.phoneNumberId || null;
      payload.channel = rec.channel || conversationChannel(rec.userId);
      payload.source_event_id = cleanRuntimeText(rec.sourceEventId || rec.source_event_id, 500) || null;
    }
    if (rec.eval !== undefined) payload.eval = rec.eval;
    const upsert = !!payload.source_event_id;
    const target = SUPABASE_URL + "/rest/v1/" + SUPABASE_TABLE +
      (upsert ? "?on_conflict=tenant_id,channel,source_event_id" : "");
    await axios.post(target, payload, {
      headers: Object.assign({
        Prefer: upsert ? "resolution=merge-duplicates,return=minimal" : "return=minimal"
      }, SB_HEADERS),
      timeout: 8000
    });
    invalidateLatestToolStateCache(rec.tools, rec.tenantId);
  } catch (e) { console.error("supabaseInsert error:", e.response ? JSON.stringify(e.response.data).slice(0,200) : e.message); }
}
async function supabaseInsertStrict(rec) {
  if (!SUPABASE_ENABLED) throw new Error("supabase_not_configured");
  const payload = {
    ts: rec.ts, user_id: rec.userId, user_message: encryptStoredText(rec.userMessage, DATA_ENCRYPTION_KEY), bot_reply: encryptStoredText(rec.botReply, DATA_ENCRYPTION_KEY),
    tools: rec.tools, zero_result_queries: rec.zeroResultQueries, handoff: rec.handoff,
    rating: rec.rating, num_tools: rec.numTools, status: rec.status
  };
  if (SUPABASE_TENANT_COLUMNS_ENABLED) {
    payload.tenant_id = rec.tenantId || DEFAULT_TENANT_ID;
    payload.phone_number_id = rec.phoneNumberId || null;
    payload.channel = rec.channel || conversationChannel(rec.userId);
    payload.source_event_id = cleanRuntimeText(rec.sourceEventId || rec.source_event_id, 500) || null;
  }
  if (rec.eval !== undefined) payload.eval = rec.eval;
  const upsert = !!payload.source_event_id;
  const target = SUPABASE_URL + "/rest/v1/" + SUPABASE_TABLE +
    (upsert ? "?on_conflict=tenant_id,channel,source_event_id" : "");
  await axios.post(target, payload, {
    headers: Object.assign({
      Prefer: upsert ? "resolution=merge-duplicates,return=minimal" : "return=minimal"
    }, SB_HEADERS),
    timeout: 8000
  });
  invalidateLatestToolStateCache(rec.tools, rec.tenantId);
}
function latestToolStateCacheKey(toolName, tenantId) {
  return String(toolName || "") + "\u001f" + (cleanTenantId(tenantId) || "*");
}
function invalidateLatestToolStateCache(tools, tenantId) {
  (Array.isArray(tools) ? tools : []).forEach(function (toolName) {
    latestToolStateCache.delete(latestToolStateCacheKey(toolName, tenantId));
    latestToolStateCache.delete(latestToolStateCacheKey(toolName, null));
  });
}
async function supabaseFetchLatestToolStates(toolName, options) {
  if (!SUPABASE_ENABLED) return null;
  options = options || {};
  const tenantId = cleanTenantId(options.tenantId);
  const cacheKey = latestToolStateCacheKey(toolName, tenantId);
  const cached = latestToolStateCache.get(cacheKey);
  if (!options.force && cached && Date.now() - cached.loaded_at < SUPABASE_STATE_CACHE_TTL_MS) return cached.rows.slice();
  try {
    const response = await axios.post(SUPABASE_URL + "/rest/v1/rpc/platform_latest_conversation_tool_states_v1", {
      p_tool: String(toolName || ""),
      p_tenant_id: tenantId || null
    }, {
      headers: SB_HEADERS,
      timeout: 8000
    });
    const rows = Array.isArray(response.data) ? response.data : [];
    if (rows.length || process.env.NODE_ENV !== "test") {
      latestToolStateCache.set(cacheKey, { loaded_at: Date.now(), rows: rows.slice() });
      return rows;
    }
    throw Object.assign(new Error("test_rpc_unavailable"), { response: { status: 404, data: { code: "PGRST202" } } });
  } catch (error) {
    const status = error && error.response && error.response.status;
    const code = error && error.response && error.response.data && error.response.data.code;
    if (status !== 404 && code !== "PGRST202") throw error;
    const rows = await supabaseFetchToolRecent(toolName, 3000, tenantId ? { tenantId } : { allTenants: true });
    latestToolStateCache.set(cacheKey, { loaded_at: Date.now(), rows: (rows || []).slice() });
    return rows || [];
  }
}
async function supabaseFetchCustomerPanelPage(limit, options) {
  if (!SUPABASE_ENABLED) return null;
  options = options || {};
  const tenantId = cleanTenantId(options.tenantId);
  if (!tenantId) return [];
  const before = options.before && Number.isFinite(Date.parse(options.before)) ? new Date(options.before).toISOString() : null;
  try {
    const response = await axios.post(SUPABASE_URL + "/rest/v1/rpc/platform_customer_panel_recent_turns_v1", {
      p_tenant_id: tenantId,
      p_limit: limit,
      p_before: before
    }, {
      headers: SB_HEADERS,
      timeout: 8000
    });
    const rows = Array.isArray(response.data) ? response.data : [];
    if (rows.length || process.env.NODE_ENV !== "test") return rows;
    throw Object.assign(new Error("test_rpc_unavailable"), { response: { status: 404, data: { code: "PGRST202" } } });
  } catch (error) {
    const status = error && error.response && error.response.status;
    const code = error && error.response && error.response.data && error.response.data.code;
    if (status !== 404 && code !== "PGRST202") throw error;
    const logic = CUSTOMER_PANEL_INTERNAL_STATE_TOOLS.map(function (toolName) {
      return "tools.not.cs." + JSON.stringify([toolName]);
    }).join(",");
    const response = await axios.get(SUPABASE_URL + "/rest/v1/" + SUPABASE_TABLE, {
      params: {
        select: CUSTOMER_PANEL_TURN_COLUMNS,
        tenant_id: "eq." + tenantId,
        ...(before ? { ts: "lt." + before } : {}),
        and: "(" + logic + ")",
        order: "ts.desc",
        limit
      },
      headers: SB_HEADERS,
      timeout: 8000
    });
    return (Array.isArray(response.data) ? response.data : []).map(function (row) {
      return Object.assign({ row_kind: "turn" }, row);
    });
  }
}
async function loadCustomerPanelActivityRows(tenantId) {
  const cleanTenant = cleanTenantId(tenantId);
  if (!cleanTenant) return { rows: [], source: "unavailable", complete: false };
  const cached = customerPanelActivityCache.get(cleanTenant);
  if (cached && Date.now() - cached.loaded_at < 60 * 1000) return cached.value;
  const since = new Date(Date.now() - 8 * 24 * 60 * 60 * 1000).toISOString();
  let value;
  if (!SUPABASE_ENABLED) {
    value = {
      rows: conversationLogs.filter(function (row) {
        return cleanTenantId(row.tenantId || row.tenant_id) === cleanTenant && Date.parse(row.ts || "") >= Date.parse(since);
      }),
      source: "memory_7d",
      complete: true
    };
  } else {
    const rows = [];
    const pageSize = 1000;
    const maxRows = 20000;
    let offset = 0;
    let complete = true;
    try {
      while (offset < maxRows) {
        const response = await axios.get(SUPABASE_URL + "/rest/v1/" + SUPABASE_TABLE, {
          params: {
            select: "ts,tenant_id,channel,user_id,user_message,tools",
            tenant_id: "eq." + cleanTenant,
            ts: "gte." + since,
            order: "ts.asc",
            limit: pageSize,
            offset
          },
          headers: SB_HEADERS,
          timeout: 8000
        });
        const page = Array.isArray(response.data) ? response.data : [];
        rows.push.apply(rows, page);
        if (page.length < pageSize) break;
        offset += pageSize;
      }
      if (rows.length >= maxRows) complete = false;
      value = {
        rows: rows.map(function (row) { return normalizeTurnRow(row); }).filter(function (row) { return !isInternalAdminTurn(row); }),
        source: complete ? "supabase_7d" : "supabase_partial_7d",
        complete
      };
    } catch (error) {
      console.error("customer panel activity query error:", error.message);
      value = { rows: [], source: "unavailable", complete: false };
    }
  }
  customerPanelActivityCache.set(cleanTenant, { loaded_at: Date.now(), value });
  return value;
}
async function supabaseFetchSourceEventStrict(tenantId, channel, sourceEventId) {
  if (!SUPABASE_ENABLED || !SUPABASE_TENANT_COLUMNS_ENABLED) throw new Error("supabase_source_event_not_configured");
  const response = await axios.get(SUPABASE_URL + "/rest/v1/" + SUPABASE_TABLE, {
    params: {
      select: "*",
      tenant_id: "eq." + cleanTenantId(tenantId),
      channel: "eq." + cleanChannel(channel),
      source_event_id: "eq." + cleanRuntimeText(sourceEventId, 500),
      limit: 1
    },
    headers: SB_HEADERS,
    timeout: 8000
  });
  if (!Array.isArray(response.data)) throw new Error("supabase_source_event_invalid_response");
  return response.data[0] ? normalizeTurnRow(response.data[0], { strict: true }) : null;
}
