const appointmentReminderService = createAppointmentReminderService({
  loadAppointments: loadUpcomingAppointmentsForReminderWorker,
  loadConfiguration: appointmentReminderConfiguration,
  persist: async function (row) {
    await persistAppointment(row);
    appointmentRegistry.hydrate([row]);
  },
  deliver: async function (appointment, template, params) {
    if (await whatsappCustomerServiceWindowOpen(appointment.tenant_id, appointment.customer_phone)) {
      const deliveryResult = {};
      const sent = await sendText(appointment.customer_phone, appointmentReminderMessage({
        tenant_id: appointment.tenant_id,
        customer_name: params.customer_name
      }, appointment), {
        tenant_id: appointment.tenant_id,
        human_agent: false,
        delivery_result: deliveryResult
      });
      return {
        ok: !!sent,
        provider_id: deliveryResult.provider_message_id || "",
        mode: "text"
      };
    }
    const delivery = await metaMessageHub.request({
      tenant_id: appointment.tenant_id,
      channel: "whatsapp",
      source: "appointment",
      use_case: "appointment_reminder",
      recipient: appointment.customer_phone,
      parameters: params,
      idempotency_key: ["legacy-reminder", appointment.appointment_id || appointment.id, appointment.starts_at, template].join(":")
    });
    return {
      ok: delivery.status === "accepted",
      provider_id: delivery.provider_message_id,
      mode: "template",
      mechanism: delivery.mechanism
    };
  }
});

const appointmentConfirmationService = createAppointmentConfirmationService({
  backfillHours: APPOINTMENT_CONFIRMATION_BACKFILL_HOURS,
  loadAppointments: loadUpcomingAppointmentsForReminderWorker,
  loadConfiguration: appointmentReminderConfiguration,
  persist: async function (row) {
    await persistAppointment(row);
    appointmentRegistry.hydrate([row]);
  },
  deliver: async function (appointment, message) {
    const tenantId = cleanTenantId(appointment && appointment.tenant_id);
    const phone = cleanRuntimeText(appointment && appointment.customer_phone, 80);
    if (!await whatsappCustomerServiceWindowOpen(tenantId, phone)) {
      return { ok: false, error: { message: "whatsapp_customer_window_closed" } };
    }
    const delivery = {};
    const sent = await sendText(phone, message, { tenant_id: tenantId, delivery_result: delivery });
    return {
      ok: sent === true,
      provider_id: delivery.provider_message_id || "customer_window_text",
      mode: "text",
      error: sent === true ? null : { message: delivery.message || "whatsapp_confirmation_failed" }
    };
  }
});
let appointmentRemindersProcessing = false;
let appointmentConfirmationsProcessing = false;

async function processAppointmentReminders() {
  if (!APPOINTMENT_REMINDERS_ENABLED || appointmentRemindersProcessing) return null;
  appointmentRemindersProcessing = true;
  try {
    const outcome = await appointmentReminderService.process();
    if (outcome.programmed || outcome.delivered || outcome.retrying || outcome.blocked) {
      log(outcome.retrying || outcome.blocked ? "warn" : "info", "appointment_reminders_processed", outcome);
    }
    return outcome;
  } catch (error) {
    log("warn", "appointment_reminders_failed", { error: cleanRuntimeText(error && error.message, 240) });
    return null;
  } finally {
    appointmentRemindersProcessing = false;
  }
}

async function processAppointmentConfirmations() {
  if (!APPOINTMENT_CONFIRMATIONS_ENABLED || appointmentConfirmationsProcessing) return null;
  appointmentConfirmationsProcessing = true;
  try {
    const outcome = await appointmentConfirmationService.process();
    if (outcome.delivered || outcome.retrying) {
      log(outcome.retrying ? "warn" : "info", "appointment_confirmations_processed", outcome);
    }
    return outcome;
  } catch (error) {
    log("warn", "appointment_confirmations_failed", { error: cleanRuntimeText(error && error.message, 240) });
    return null;
  } finally {
    appointmentConfirmationsProcessing = false;
  }
}

if (APPOINTMENT_REMINDERS_ENABLED) {
  const appointmentReminderTimer = setInterval(processAppointmentReminders, APPOINTMENT_REMINDER_INTERVAL_MS);
  if (appointmentReminderTimer.unref) appointmentReminderTimer.unref();
  setTimeout(processAppointmentReminders, 5000);
}

if (APPOINTMENT_CONFIRMATIONS_ENABLED) {
  const appointmentConfirmationTimer = setInterval(processAppointmentConfirmations, APPOINTMENT_REMINDER_INTERVAL_MS);
  if (appointmentConfirmationTimer.unref) appointmentConfirmationTimer.unref();
  setTimeout(processAppointmentConfirmations, 7000);
}

async function sendImage(to, imageUrl, caption, options) {
  const recipient = parseChannelRecipient(to);
  let deliveryRuntime = options || (recipient.channel === "whatsapp" ? cachedConversationRuntime(to, null) : null);
  try {
    if (recipient.channel === "instagram") {
      const runtime = await outboundRuntimeForConversation(to, options);
      const accessToken = runtime && runtime.accessToken;
      const sendId = runtime && runtime.instagramUserId;
      const graphOrigin = instagramGraphOriginForRuntime(runtime);
      if (!accessToken || !sendId) throw new Error("Instagram messaging is not configured");
      await axios.post(
        `${graphOrigin}/${META_GRAPH_VERSION}/${sendId}/messages`,
        { recipient: { id: recipient.id }, message: { attachment: { type: "image", payload: { url: imageUrl } } } },
        { headers: { Authorization: `Bearer ${accessToken}`, "Content-Type": "application/json" }, timeout: 10000 }
      );
      if (caption) await sendText(to, caption, runtime);
      return true;
    }
    if (recipient.channel === "messenger") {
      const runtime = await outboundRuntimeForConversation(to, options);
      const accessToken = runtime && runtime.accessToken;
      const pageId = runtime && runtime.pageId;
      if (!accessToken || !pageId) throw new Error("Messenger messaging is not configured");
      await axios.post(
        `${MESSENGER_GRAPH_BASE_URL}/${META_GRAPH_VERSION}/${pageId}/messages`,
        {
          recipient: { id: recipient.id },
          messaging_type: "RESPONSE",
          message: { attachment: { type: "image", payload: { url: imageUrl, is_reusable: true } } }
        },
        { headers: { Authorization: `Bearer ${accessToken}`, "Content-Type": "application/json" }, timeout: 10000 }
      );
      if (caption) await sendText(to, caption, runtime);
      return true;
    }
    const runtime = await outboundRuntimeForConversation(to, options);
    deliveryRuntime = runtime || deliveryRuntime;
    const phoneNumberId = runtime && runtime.phoneNumberId;
    const accessToken = runtime && runtime.accessToken;
    if (!phoneNumberId || !accessToken) throw new Error("WhatsApp messaging is not configured");
    await axios.post(
      `https://graph.facebook.com/${META_GRAPH_VERSION}/${phoneNumberId}/messages`,
      { messaging_product: "whatsapp", to: recipient.id, type: "image", image: { link: imageUrl, caption } },
      { headers: { Authorization: `Bearer ${accessToken}`, "Content-Type": "application/json" }, timeout: 10000 }
    );
    return true;
  } catch (err) {
    const durableInbound = recipient.channel === "whatsapp" && deliveryRuntime && (
      deliveryRuntime.requirePersistence === true || deliveryRuntime.require_persistence === true
    );
    if (durableInbound) {
      const classification = classifyWhatsAppDeliveryError(err);
      whatsappRuntimeState.last_error_at = new Date().toISOString();
      whatsappRuntimeState.last_error_stage = "send_image";
      whatsappRuntimeState.last_error_code = classification.meta_code;
      whatsappRuntimeState.last_error_subcode = classification.meta_subcode;
      if (classification.retryable) whatsappRuntimeState.retryable_outbound_failures++;
      else whatsappRuntimeState.permanent_outbound_failures++;
      throw whatsappDeliveryFailure(err);
    }
    console.error(`${channelLabel(to)} image error:`, err.response?.data?.error || err.message);
    return false;
  }
}

function mediaFilename(media) {
  const mime = String(media && media.mime_type || "").toLowerCase();
  if (media && media.kind === "image") return "whatsapp-image." + (mime.includes("png") ? "png" : "jpg");
  if (mime.includes("mpeg") || mime.includes("mp3")) return "whatsapp-audio.mp3";
  if (mime.includes("m4a")) return "whatsapp-audio.m4a";
  if (mime.includes("mp4")) return "whatsapp-audio.mp4";
  if (mime.includes("wav")) return "whatsapp-audio.wav";
  if (mime.includes("webm")) return "whatsapp-audio.webm";
  if (mime.includes("aac")) return "whatsapp-audio.aac";
  return "whatsapp-audio.ogg";
}

function extractOpenAIText(data) {
  if (data && typeof data.text === "string") return data.text.trim();
  if (data && typeof data.output_text === "string") return data.output_text.trim();
  const chunks = [];
  for (const item of data && data.output || []) {
    for (const content of item && item.content || []) {
      const text = content && typeof content.text === "string"
        ? content.text
        : (content && content.text && typeof content.text.value === "string" ? content.text.value : "");
      if (text && ["output_text", "text"].includes(content.type)) chunks.push(text);
    }
  }
  return chunks.join("\n").trim();
}

async function downloadWhatsAppMediaForMultimodal(media, context) {
  const accessToken = String(context && context.access_token || "").trim();
  if (!accessToken) throw new Error("wa_token_missing");
  const metadata = await axios.get(
    `https://graph.facebook.com/${META_GRAPH_VERSION}/${encodeURIComponent(media.media_id)}`,
    {
      params: context && context.phone_number_id ? { phone_number_id: context.phone_number_id } : undefined,
      headers: { Authorization: `Bearer ${accessToken}` },
      timeout: 10000
    }
  );
  const mediaUrl = metadata.data && metadata.data.url;
  if (!mediaUrl) throw new Error("media_url_missing");
  const response = await axios.get(mediaUrl, {
    responseType: "arraybuffer",
    headers: { Authorization: `Bearer ${accessToken}` },
    timeout: 20000,
    maxContentLength: Math.max(MULTIMODAL_CONFIG.max_audio_bytes, MULTIMODAL_CONFIG.max_image_bytes)
  });
  return {
    buffer: Buffer.from(response.data),
    mime_type: response.headers && response.headers["content-type"] || metadata.data.mime_type || media.mime_type,
    file_size: Number(metadata.data.file_size || response.data.byteLength || 0),
    sha256: metadata.data.sha256 || media.sha256 || ""
  };
}

async function transcribeMultimodalAudio(downloaded, media, context) {
  if (!OPENAI_API_KEY) throw new Error("openai_api_key_missing");
  const form = new FormData();
  form.append("model", OPENAI_TRANSCRIPTION_MODEL);
  form.append("file", new Blob([downloaded.buffer], { type: downloaded.mime_type || media.mime_type || "audio/ogg" }), mediaFilename(media));
  form.append("response_format", "json");
  let response;
  try {
    response = await axios.post("https://api.openai.com/v1/audio/transcriptions", form, {
      headers: { Authorization: `Bearer ${OPENAI_API_KEY}` },
      timeout: 45000,
      maxBodyLength: MULTIMODAL_CONFIG.max_audio_bytes + 1024 * 1024
    });
  } catch (error) {
    captureAiUsage({
      provider: "openai",
      model: OPENAI_TRANSCRIPTION_MODEL,
      tenant_id: context && context.tenant_id,
      user_id: context && context.user_id,
      channel: conversationChannel(context && context.user_id),
      bot_id: "multimodal",
      feature: "audio_transcription",
      status: "error",
      error
    });
    throw error;
  }
  captureAiUsage({
    provider: "openai",
    model: OPENAI_TRANSCRIPTION_MODEL,
    tenant_id: context && context.tenant_id,
    user_id: context && context.user_id,
    channel: conversationChannel(context && context.user_id),
    bot_id: "multimodal",
    feature: "audio_transcription",
    usage: response.data && response.data.usage
  });
  const text = extractOpenAIText(response.data);
  if (!text) throw new Error("transcription_empty");
  return { text, provider: "openai", model: OPENAI_TRANSCRIPTION_MODEL };
}

async function multimodalBotModeForTenant(tenantId) {
  const cleanTenant = cleanTenantId(tenantId);
  try {
    const onboarding = cleanTenant ? await loadClientOnboarding(false, cleanTenant) : null;
    const answers = onboarding && onboarding.answers || {};
    const goal = String(answers.setup_goal || "").trim().toLowerCase();
    if (goal === "appointments") return "appointments";
    if (goal === "both") return "both";
    if (goal === "customer_service") return "customer_service";
    const assignedBot = String(onboarding && onboarding.assigned_bot_id || answers.selected_bot_id || "").trim().toLowerCase();
    if (["agendamiento", "appointments", "appointment"].includes(assignedBot)) return "appointments";
    if (["both", "duo"].includes(assignedBot)) return "both";
    if (["atencion-cliente", "customer_service", "customer-service"].includes(assignedBot)) return "customer_service";
    if (assignedBot) return "generic";
  } catch (error) {
    log("warn", "multimodal_bot_mode_lookup_failed", {
      tenant_id: cleanTenant,
      error: String(error && error.message || "lookup_failed").slice(0, 160)
    });
  }
  const registered = getRegisteredClient(cleanTenant);
  if (registered && registered.modules && registered.modules.appointments) return "appointments";
  if ([DEFAULT_TENANT_ID, CHANNEL_CONNECTION_BOOTSTRAP_WHATSAPP_TENANT_ID].filter(Boolean).includes(cleanTenant)) return "customer_service";
  return "generic";
}

async function analyzeMultimodalImage(downloaded, media, context) {
  if (!OPENAI_API_KEY) throw new Error("openai_api_key_missing");
  const mime = downloaded.mime_type || media.mime_type || "image/jpeg";
  const dataUrl = "data:" + mime + ";base64," + downloaded.buffer.toString("base64");
  const botMode = await multimodalBotModeForTenant(context && context.tenant_id);
  let response;
  try {
    response = await axios.post("https://api.openai.com/v1/responses", {
      model: OPENAI_VISION_MODEL,
      max_output_tokens: 450,
      input: [{
        role: "user",
        content: [
          {
            type: "input_text",
            text: imageAnalysisPrompt(botMode)
          },
          { type: "input_image", image_url: dataUrl }
        ]
      }]
    }, {
      headers: { Authorization: `Bearer ${OPENAI_API_KEY}`, "Content-Type": "application/json" },
      timeout: 45000,
      maxBodyLength: MULTIMODAL_CONFIG.max_image_bytes + 1024 * 1024
    });
  } catch (error) {
    captureAiUsage({
      provider: "openai",
      model: OPENAI_VISION_MODEL,
      tenant_id: context && context.tenant_id,
      user_id: context && context.user_id,
      channel: conversationChannel(context && context.user_id),
      bot_id: botMode === "appointments" ? "appointment" : "customer_service",
      feature: "image_analysis",
      status: "error",
      error
    });
    throw error;
  }
  captureAiUsage({
    provider: "openai",
    model: OPENAI_VISION_MODEL,
    tenant_id: context && context.tenant_id,
    user_id: context && context.user_id,
    channel: conversationChannel(context && context.user_id),
    bot_id: botMode === "appointments" ? "appointment" : "customer_service",
    feature: "image_analysis",
    usage: response.data && response.data.usage,
    context_messages: 1
  });
  const text = extractOpenAIText(response.data);
  if (!text) throw new Error("vision_empty");
  return { text, provider: "openai", model: OPENAI_VISION_MODEL };
}

async function sendLocation(to, lat, lng, name, address, options) {
  if (["instagram", "messenger"].includes(parseChannelRecipient(to).channel)) {
    await sendText(to, `${name}\n${address}\nhttps://www.google.com/maps?q=${lat},${lng}`);
    return;
  }
  let deliveryRuntime = options || cachedConversationRuntime(to, null);
  try {
    const runtime = await outboundRuntimeForConversation(to, options);
    deliveryRuntime = runtime || deliveryRuntime;
    const phoneNumberId = runtime && runtime.phoneNumberId;
    const accessToken = runtime && runtime.accessToken;
    if (!phoneNumberId || !accessToken) throw new Error("WhatsApp messaging is not configured");
    await axios.post(
      `https://graph.facebook.com/${META_GRAPH_VERSION}/${phoneNumberId}/messages`,
      { messaging_product: "whatsapp", to, type: "location", location: { latitude: lat, longitude: lng, name, address } },
      { headers: { Authorization: `Bearer ${accessToken}`, "Content-Type": "application/json" }, timeout: 10000 }
    );
  } catch (err) {
    const durableInbound = deliveryRuntime && (
      deliveryRuntime.requirePersistence === true || deliveryRuntime.require_persistence === true
    );
    if (durableInbound) {
      const classification = classifyWhatsAppDeliveryError(err);
      whatsappRuntimeState.last_error_at = new Date().toISOString();
      whatsappRuntimeState.last_error_stage = "send_location";
      whatsappRuntimeState.last_error_code = classification.meta_code;
      whatsappRuntimeState.last_error_subcode = classification.meta_subcode;
      if (classification.retryable) whatsappRuntimeState.retryable_outbound_failures++;
      else whatsappRuntimeState.permanent_outbound_failures++;
      throw whatsappDeliveryFailure(err);
    }
    console.error("WA location error:", err.response?.data?.error || err.message);
  }
}

// Logger estructurado (v32) — formato JSON para futura integración con servicios externos
function log(level, event, data = {}) {
  const entry = { ts: new Date().toISOString(), level, event, ...data };
  if (level === 'error') {
    console.error(JSON.stringify(entry));
  } else {
    console.log(JSON.stringify(entry));
  }
}

async function notifyTeam(text, excludePhone) {
  let sent = 0;
  for (const phone of NOTIFICATION_PHONES) {
    if (excludePhone && phone === excludePhone) {
      console.log(`Skipped self-notification to ${maskedIdentifier(phone)} (is current customer)`);
      continue;
    }
    try {
      await sendText(phone, text);
      sent++;
    } catch (err) {
      console.log(`[NOTIFY] Failed to send to ${maskedIdentifier(phone)}: ${err.message || err}. Continuing with rest.`);
    }
  }
  console.log(`Notified team (${sent}/${NOTIFICATION_PHONES.length} numbers)`);
  return { sent, total: NOTIFICATION_PHONES.length };
}

async function recordAnthropicRuntimeFailure(error, tenantId, channel) {
  const incident = runtimeIncidentMonitor.failure("anthropic", tenantId, error);
  await recordBotOpsEvent({
    tenant_id: tenantId,
    bot_id: "customer_service",
    channel: channel || "unknown",
    event_type: "provider_error",
    occurred_at: incident.occurred_at,
    source_id: "anthropic:" + incident.occurred_at,
    payload: {
      provider: "anthropic",
      error_type: incident.error_type,
      status: incident.status,
      consecutive_failures: incident.consecutive_failures,
      retryable: ![400, 401, 403, 404, 422].includes(incident.status)
    }
  });
  log("error", "conversation_provider_failure", {
    provider: incident.provider,
    tenant_id: incident.tenant_id,
    channel: cleanRuntimeText(channel, 40) || "unknown",
    error_type: incident.error_type,
    error_message: incident.error_message,
    status: incident.status,
    consecutive_failures: incident.consecutive_failures,
    retryable: ![400, 401, 403, 404, 422].includes(incident.status)
  });
  if (!incident.should_alert) return incident;
  try {
    await notifyTeam([
      "⚠️ *ALERTA DE BOT NEXTFOR IA*",
      "",
      "Proveedor: Anthropic",
      `Cliente: ${incident.tenant_id}`,
      `Canal: ${cleanRuntimeText(channel, 40) || "unknown"}`,
      `Error: ${incident.error_type}`,
      `Fallos en 5 minutos: ${incident.consecutive_failures}`,
      "",
      "Revisar Bandeja de operación y logs de producción."
    ].join("\n"), null);
  } catch (alertError) {
    log("error", "conversation_provider_alert_failed", {
      provider: "anthropic",
      tenant_id: incident.tenant_id,
      error: cleanRuntimeText(alertError && alertError.message, 160) || "alert_failed"
    });
  }
  return incident;
}

