app.get("/whatsapp/health", async (req, res) => {
  const checkedAt = new Date().toISOString();
  const bootstrap = await channelConnectionBootstrapPromise;
  const healthTenantId = cleanTenantId(CHANNEL_CONNECTION_WHATSAPP_RUNTIME_TENANT_ID);
  let durableConnection = null;
  try {
    durableConnection = channelConnectionStore && await channelConnectionStore.get(healthTenantId, "whatsapp");
  } catch (error) {
    log("warn", "whatsapp_health_connection_state_unavailable", {
      tenant_id: healthTenantId,
      error: cleanRuntimeText(error && error.message, 240)
    });
  }
  const outboundBillingBlocked = !!(durableConnection && durableConnection.status === "connected" &&
    durableConnection.webhook_status === "outbound_billing_blocked");
  const runtime = await resolveWhatsAppRuntimeForTenant(healthTenantId);
  const phoneNumberId = runtime && runtime.phoneNumberId;
  const whatsappBusinessAccountId = runtime && (
    runtime.whatsappBusinessAccountId || runtime.whatsapp_business_account_id
  );
  const accessToken = runtime && runtime.accessToken;
  const safeRuntime = Object.assign({}, whatsappRuntimeState, {
    outbound_billing_blocked: outboundBillingBlocked,
    runtime_source: runtime && runtime.source || null,
    tenant_id: cleanTenantId(runtime && (runtime.tenantId || runtime.tenant_id)) || null,
    phone_number_suffix: String(phoneNumberId || "").slice(-8) || null,
    waba_suffix: String(whatsappBusinessAccountId || "").slice(-8) || null,
    bootstrap: {
      ok: bootstrap && bootstrap.ok !== false,
      skipped: !!(bootstrap && bootstrap.skipped),
      reason: bootstrap && bootstrap.reason || null,
      error: bootstrap && bootstrap.error ? String(bootstrap.error).slice(0, 300) : null,
      registration: bootstrap && bootstrap.registration || null
    }
  });
  if (outboundBillingBlocked) {
    return res.status(503).json({
      ok: false,
      configured: true,
      status: "outbound_billing_blocked",
      outbound_billing_blocked: true,
      message: "Meta bloqueó las respuestas de WhatsApp (131042). Agrega un método de pago válido en WhatsApp Manager.",
      checked_at: checkedAt,
      runtime: safeRuntime
    });
  }
  if (!phoneNumberId || !accessToken) {
    return res.status(503).json({
      ok: false,
      configured: false,
      status: "not_configured",
      checked_at: checkedAt,
      runtime: safeRuntime
    });
  }
  try {
    const phone = await axios.get(`https://graph.facebook.com/${META_GRAPH_VERSION}/${encodeURIComponent(phoneNumberId)}`, {
      params: {
        fields: "id,display_phone_number,verified_name,quality_rating,code_verification_status,platform_type"
      },
      headers: { Authorization: `Bearer ${accessToken}` },
      timeout: 10000
    });
    safeRuntime.phone = {
      code_verification_status: cleanRuntimeText(phone.data && phone.data.code_verification_status, 60) || null,
      platform_type: cleanRuntimeText(phone.data && phone.data.platform_type, 60) || null,
      quality_rating: cleanRuntimeText(phone.data && phone.data.quality_rating, 60) || null,
      registration_ready: String(phone.data && phone.data.code_verification_status || "").toUpperCase() === "VERIFIED" &&
        String(phone.data && phone.data.platform_type || "").toUpperCase() === "CLOUD_API"
    };
    if (whatsappBusinessAccountId) {
      try {
        const waba = await axios.get(
          `https://graph.facebook.com/${META_GRAPH_VERSION}/${encodeURIComponent(whatsappBusinessAccountId)}`,
          {
            params: { fields: "id,name,owner_business_info,account_review_status" },
            headers: { Authorization: `Bearer ${accessToken}` },
            timeout: 10000
          }
        );
        safeRuntime.waba = {
          id_suffix: String(waba.data && waba.data.id || "").slice(-8) || null,
          name: cleanRuntimeText(waba.data && waba.data.name, 160) || null,
          owner_business_id: cleanRuntimeText(
            waba.data && waba.data.owner_business_info && waba.data.owner_business_info.id,
            240
          ) || null,
          owner_business_name: cleanRuntimeText(
            waba.data && waba.data.owner_business_info && waba.data.owner_business_info.name,
            160
          ) || null,
          account_review_status: cleanRuntimeText(waba.data && waba.data.account_review_status, 60) || null
        };
      } catch (diagnosticError) {
        safeRuntime.waba = {
          id_suffix: String(whatsappBusinessAccountId).slice(-8) || null,
          diagnostic_error: cleanRuntimeText(
            diagnosticError.response && diagnosticError.response.data &&
              diagnosticError.response.data.error && diagnosticError.response.data.error.message ||
              diagnosticError.message,
            240
          ) || "waba_lookup_failed"
        };
      }
    }
    if (!safeRuntime.phone.registration_ready) {
      return res.status(503).json({
        ok: false,
        configured: true,
        status: "registration_incomplete",
        checked_at: checkedAt,
        runtime: safeRuntime
      });
    }
    if (!whatsappBusinessAccountId) {
      return res.status(503).json({
        ok: false,
        configured: true,
        status: "waba_not_configured",
        checked_at: checkedAt,
        runtime: safeRuntime
      });
    }
    const subscription = await axios.get(
      `https://graph.facebook.com/${META_GRAPH_VERSION}/${encodeURIComponent(whatsappBusinessAccountId)}/subscribed_apps`,
      {
        headers: { Authorization: `Bearer ${accessToken}` },
        timeout: 10000
      }
    );
    const appSubscribed = !!META_APP_ID && (
      subscription.data && Array.isArray(subscription.data.data) ? subscription.data.data : []
    ).some(function (app) {
      return String(app && (
        app.id || app.whatsapp_business_api_data && app.whatsapp_business_api_data.id
      )) === String(META_APP_ID);
    });
    if (!appSubscribed) {
      return res.status(503).json({
        ok: false,
        configured: true,
        status: "webhook_not_subscribed",
        checked_at: checkedAt,
        runtime: safeRuntime
      });
    }
    return res.json({
      ok: true,
      configured: true,
      status: "connected",
      checked_at: checkedAt,
      runtime: safeRuntime
    });
  } catch (err) {
    const metaError = err.response?.data?.error || {};
    return res.status(503).json({
      ok: false,
      configured: true,
      status: "api_error",
      error_code: metaError.code || null,
      error_type: metaError.type || "request_failed",
      checked_at: checkedAt,
      runtime: safeRuntime
    });
  }
});

