async function serveCustomerOnboarding(req, res, options) {
  options = options || {};
  // Editing a completed setup has its own stable URL. Do not rely on a query
  // parameter here: browsers/PWA history can restore a cached non-edit route.
  const editMode = !!options.editMode || req.query.edit === "1";
  const targetPath = editMode ? "/admin/client-onboarding/edit" : "/admin/client-onboarding";
  const auth = dashboardAuth(req);
  if (!auth.ok || !customerPanelAuthOk(req, "admin")) {
    if (CUSTOMER_ACCESS_V2_ENABLED) renderCustomerLogin(res, { targetPath });
    else renderAdminLogin(res, targetPath);
    return;
  }
  // The form contains tenant data. Never permit an authenticated browser or
  // installed web app to reuse an older document from a previous navigation.
  res.setHeader("Cache-Control", "private, no-store, max-age=0");
  res.setHeader("Pragma", "no-cache");
  if (auth.method === "key") setDashboardSessionCookie(req, res, auth);
  const tenantId = customerTenantForAuth(auth);
  const record = await loadClientOnboarding(false, tenantId);
  const questionnaire = await loadCustomerSetupQuestionnaire(true);
  const reviewStatus = record.setup_review && record.setup_review.status || "";
  if (auth.version === 2 && record.setup_completed && reviewStatus !== "incomplete" && !editMode) {
    res.redirect(await customerPanelNextPathAfterSetup(auth, record, "onboarding"));
    return;
  }
  let catalogs = { plans: [], bots: [] };
  const appointmentSetupVisible = appointmentSetupEnabledForAuth(auth);
  const appointmentCatalog = { appointmentsVisible: appointmentSetupVisible };
  if (CUSTOMER_ACCESS_V2_ENABLED && catalogService) {
    try { catalogs = catalogWithDefaults(await catalogService.activeCatalogs(), true, appointmentCatalog); }
    catch (_) { catalogs = catalogWithDefaults(null, true, appointmentCatalog); }
  }
  const business = customerBusinessForAuth(auth);
  const plan = (catalogs.plans || []).find(function (item) { return item.id === business.plan_id; }) || null;
  const bot = (catalogs.bots || []).find(function (item) { return item.id === business.assigned_bot_id; }) || null;
  let billing = null;
  if (PAYMENTS_V1_ENABLED && paymentService) {
    try { billing = await paymentService.tenantBilling(tenantId); }
    catch (_) {}
  }
  const displayRecord = JSON.parse(JSON.stringify(record));
  displayRecord.answers = displayRecord.answers || defaultClientOnboarding();
  if (!displayRecord.answers.business.brand_name) displayRecord.answers.business.brand_name = business.name;
  if (!displayRecord.answers.team.admin_email) displayRecord.answers.team.admin_email = auth.email || auth.username;
  if (!displayRecord.answers.business.contact_email) displayRecord.answers.business.contact_email = auth.email || auth.username;
  renderClientOnboarding(res, {
    tenant: business,
    record: displayRecord,
    actor: auth.name || auth.username,
    adminEmail: auth.email || auth.username,
    plan,
    plans: catalogs.plans || [],
    bot,
    bots: catalogs.bots || [],
    billing,
    paymentsV1Enabled: PAYMENTS_V1_ENABLED,
    demo: false,
    apiPath: "/admin/client-onboarding/data",
    shopifyConnectPath: "/admin/integrations/shopify/connect",
    chatbotOnlyRelease: !appointmentSetupVisible,
    completionPath: customerSetupCompletionPath(auth, "onboarding"),
    returnPath: editMode ? "/admin/panel?tab=setup" : "",
    questionnaire,
    focusPending: req.query.focus === "pending"
  });
}

