function channelConnectionActor(auth) {
  return auth && (auth.email || auth.username || auth.user_id || auth.name) || "system";
}

function channelConnectionErrorResponse(res, error) {
  const problem = error instanceof ChannelConnectionError
    ? error
    : new ChannelConnectionError("channel_connection_unavailable", 503, error && error.message);
  const customerCodes = [
    "invalid_channel_request",
    "channel_oauth_not_configured",
    "connection_selection_expired",
    "invalid_asset_selection",
    "connection_not_found",
    "legacy_connection_protected",
    "channel_asset_already_assigned",
    "asset_activation_failed",
    "whatsapp_activation_rate_limited",
    "whatsapp_registration_pin_required",
    "whatsapp_activation_in_progress",
    "existing_asset_credentials_required",
    "whatsapp_onboarding_attempt_active",
    "whatsapp_business_app_number_not_supported",
    "whatsapp_coexistence_event_required",
    "whatsapp_coexistence_number_required",
    "whatsapp_onboarding_mode_mismatch",
    "whatsapp_phone_already_connected",
    "whatsapp_onboarding_cannot_cancel",
    "whatsapp_activation_retired",
    "active_connection_must_be_disconnected"
  ];
  res.status(problem.status || 503).json({
    ok: false,
    error: customerCodes.includes(problem.code) ? problem.code : "channel_connection_failed",
    message: problem.code === "channel_oauth_not_configured"
      ? "Aún estamos preparando este paso. Habla con NextforIA."
      : problem.code === "legacy_connection_protected"
        ? "No se puede cambiar esta conexión desde aquí."
        : problem.code === "channel_asset_already_assigned"
          ? "Esta cuenta ya está conectada a otra empresa. Desconéctala allí antes de asignarla de nuevo."
        : problem.code === "existing_asset_credentials_required"
          ? "La autorización guardada no está completa. Vuelve a conectar WhatsApp con Meta."
        : problem.code === "whatsapp_activation_rate_limited"
          ? "Meta bloqueó temporalmente este número. Nextfor no repetirá el registro; descarta el intento cuando esté disponible y conecta un número diferente."
        : problem.code === "whatsapp_registration_pin_required"
          ? "Crea un PIN de seguridad de seis dígitos para WhatsApp."
        : problem.code === "whatsapp_activation_in_progress"
          ? "Ya hay una activación de este número en curso. Espera el resultado antes de volver a enviarla."
        : problem.code === "whatsapp_onboarding_attempt_active"
          ? "Ya hay una conexión de WhatsApp en curso. Cancélala antes de empezar otra."
        : problem.code === "whatsapp_business_app_number_not_supported"
          ? "Elige Conservar mi WhatsApp Business para usar ese número en coexistencia."
        : problem.code === "whatsapp_coexistence_event_required"
          ? "Meta no confirmó la coexistencia. Vuelve a empezar y elige Conservar mi WhatsApp Business."
        : problem.code === "whatsapp_coexistence_number_required"
          ? "La coexistencia solo funciona con un número activo en la app WhatsApp Business."
        : problem.code === "whatsapp_onboarding_mode_mismatch"
          ? "Ese número requiere la otra opción de conexión. Cancela el intento y elige Conservar mi WhatsApp Business."
        : problem.code === "whatsapp_phone_already_connected"
          ? "Ese número ya está activo en WhatsApp Cloud API. Para esta conexión usa un número nuevo."
        : problem.code === "whatsapp_onboarding_cannot_cancel"
          ? "Meta ya empezó a registrar este número. Nextfor solo comprobará el resultado y no repetirá el registro."
        : problem.code === "whatsapp_activation_retired"
          ? "Conecta WhatsApp desde el botón del Customer Panel."
        : problem.code === "active_connection_must_be_disconnected"
          ? "Desconecta el WhatsApp actual antes de conectar otro número."
        : problem.code === "asset_activation_failed"
          ? "Meta no pudo terminar esta conexión. Nextfor no repetirá el registro automáticamente."
        : "No pudimos terminar este paso. Intenta de nuevo o habla con NextforIA."
  });
}

function isChannelConnectionMutationRequest(req) {
  const requestPath = String(req.path || "");
  if (req.method === "GET") {
    return requestPath === "/admin/channel-connections/meta/callback";
  }
  if (!["POST", "PUT", "PATCH", "DELETE"].includes(req.method)) return false;
  return requestPath.startsWith("/admin/panel/channel-connections/") ||
    requestPath.startsWith("/admin/channel-connections/");
}

app.use(function channelConnectionMutationMaintenance(req, res, next) {
  if (CHANNEL_CONNECTIONS_MUTATIONS_ENABLED || !isChannelConnectionMutationRequest(req)) {
    next();
    return;
  }
  res.set("Retry-After", "120");
  if (req.method === "GET") {
    res.redirect("/admin/panel?tab=channels&connection=maintenance");
    return;
  }
  res.status(503).json({
    ok: false,
    error: "channel_connections_maintenance",
    message: "Los conectores están en mantenimiento por unos minutos. Tus canales activos siguen funcionando."
  });
});

app.get("/admin/panel/channel-connections", async (req, res) => {
  if (!CHANNEL_CONNECTIONS_V1_VISIBLE || !channelConnectionService) {
    res.status(404).json({ ok: false, error: "channel_connections_disabled" });
    return;
  }
  if (!customerPanelAuthOk(req, "viewer")) {
    res.status(401).json({ ok: false, error: "unauthorized" });
    return;
  }
  const auth = dashboardAuth(req);
  if (!await customerChannelConnectionsVisibleForPanelAuth(auth)) {
    res.status(404).json({ ok: false, error: "channel_connections_disabled" });
    return;
  }
  try {
    const tenantId = customerChannelTenantForAuth(auth);
    await channelConnectionBootstrapPromise;
    let channels = await channelConnectionService.listTenant(tenantId);
    // A "connected" badge must represent a live Meta credential and webhook
    // subscription, not only a previously saved OAuth result. Refresh stale
    // connections when the customer opens the channel hub.
    for (const connection of channels) {
      if (!CHANNEL_CONNECTIONS_MUTATIONS_ENABLED) break;
      const activationPending = connection && connection.channel === "whatsapp" &&
        connection.status === "connecting" && connection.webhook_status === "pending_activation";
      if (!connection || (connection.status !== "connected" && !activationPending)) continue;
      const verifiedAt = Date.parse(connection.last_verified_at || "");
      if (Number.isFinite(verifiedAt) && Date.now() - verifiedAt < 2 * 60 * 1000) continue;
      try {
        await channelConnectionService.verify(tenantId, connection.channel, auth);
        invalidateChannelRuntimeCache();
      } catch (error) {
        console.error("customer channel verify error:", connection.channel, error.message);
      }
    }
    channels = await channelConnectionService.listTenant(tenantId);
    let appointmentCalendar = null;
    if (await customerAppointmentCalendarVisibleForPanelAuth(auth)) {
      let calendarConnection = await appointmentCalendarService.get(tenantId);
      if (calendarConnection && calendarConnection.status === "connected") {
        const verifiedAt = Date.parse(calendarConnection.last_verified_at || "");
        if (!Number.isFinite(verifiedAt) || Date.now() - verifiedAt >= 2 * 60 * 1000) {
          try {
            calendarConnection = await appointmentCalendarService.verify(tenantId, auth);
          } catch (error) {
            console.error("customer appointment calendar verify error:", error.message);
            calendarConnection = await appointmentCalendarService.get(tenantId);
          }
        }
      }
      appointmentCalendar = Object.assign({
        id: (calendarConnection && calendarConnection.provider || "google") + "-calendar",
        name: calendarConnection && calendarConnection.provider === "microsoft" ? "Microsoft Outlook" : "Google Calendar",
        description: "Nextfor revisa disponibilidad y crea un calendario separado llamado Citas NextforIA.",
        authorization_available: appointmentCalendarService.providerConfigured(calendarConnection && calendarConnection.provider || "google")
      }, calendarConnection || {});
    }
    res.json({
      ok: true,
      channels,
      appointment_calendar: appointmentCalendar,
      appointment_calendar_providers: appointmentCalendar
        ? appointmentCalendarProvidersForConnection(appointmentCalendar)
        : [],
      meta_authorization_available: {
        whatsapp: CHANNEL_CONNECTIONS_MUTATIONS_ENABLED && publicWhatsAppOnboardingReady() && channelConnectionService.providerConfigured("whatsapp"),
        whatsapp_coexistence: CHANNEL_CONNECTIONS_MUTATIONS_ENABLED && publicWhatsAppOnboardingReady() &&
          channelConnectionService.providerConfigured("whatsapp") && !!META_WHATSAPP_COEXISTENCE_CONFIG_ID,
        instagram: CHANNEL_CONNECTIONS_MUTATIONS_ENABLED && channelConnectionService.providerConfigured("instagram"),
        messenger: CHANNEL_CONNECTIONS_MUTATIONS_ENABLED && channelConnectionService.providerConfigured("messenger")
      }
    });
  } catch (error) {
    console.error("customer channel list error:", error.message);
    channelConnectionErrorResponse(res, error);
  }
});

app.post("/admin/panel/channel-connections/:channel/connect", async (req, res) => {
  if (!CHANNEL_CONNECTIONS_V1_VISIBLE || !channelConnectionService) {
    res.status(404).json({ ok: false, error: "channel_connections_disabled" });
    return;
  }
  if (!customerPanelAuthOk(req, "admin")) {
    res.status(401).json({ ok: false, error: "unauthorized" });
    return;
  }
  const auth = dashboardAuth(req);
  if (!await customerChannelConnectionsVisibleForPanelAuth(auth)) {
    res.status(404).json({ ok: false, error: "channel_connections_disabled" });
    return;
  }
  const channel = cleanChannel(req.params.channel);
  const tenantId = customerChannelTenantForAuth(auth);
  try {
    const requestedWhatsAppMode = cleanRuntimeText(req.body && req.body.onboarding_mode, 40).toLowerCase();
    const whatsappOnboardingMode = channel === "whatsapp"
      ? requestedWhatsAppMode === "coexistence" || requestedWhatsAppMode === "coexistence_recovery"
        ? requestedWhatsAppMode
        : "cloud_api"
      : "";
    if (channel === "whatsapp" && requestedWhatsAppMode &&
        !["cloud_api", "coexistence", "coexistence_recovery"].includes(requestedWhatsAppMode)) {
      throw new ChannelConnectionError("invalid_channel_request", 400, "Unsupported WhatsApp onboarding mode");
    }
    if (["coexistence", "coexistence_recovery"].includes(whatsappOnboardingMode) &&
        !META_WHATSAPP_COEXISTENCE_CONFIG_ID) {
      throw new ChannelConnectionError("channel_oauth_not_configured", 503, "WhatsApp coexistence configuration is missing");
    }
    const whatsappAttemptId = channel === "whatsapp" ? crypto.randomUUID() : "";
    const redirectUri = channelConnectionOAuthRedirectUrlForRequest(req, channel);
    const state = createOAuthState(DASHBOARD_SESSION_SECRET, {
      tenant_id: tenantId,
      channel,
      actor_id: auth.user_id || auth.username,
      actor: channelConnectionActor(auth),
      redirect_uri: redirectUri,
      return_path: "/admin/panel?tab=channels",
      return_mode: "popup",
      whatsapp_onboarding_mode: whatsappOnboardingMode,
      whatsapp_attempt_id: whatsappAttemptId
    });
    const authorizationUrl = await channelConnectionService.begin(tenantId, channel, auth, state, {
      redirectUri,
      attemptId: whatsappAttemptId,
      whatsappOnboardingMode
    });
    if (channel === "whatsapp") {
      res.json({
        ok: true,
        embedded_signup: {
          app_id: META_APP_ID,
          configuration_id: ["coexistence", "coexistence_recovery"].includes(whatsappOnboardingMode)
            ? META_WHATSAPP_COEXISTENCE_CONFIG_ID
            : META_WHATSAPP_CONFIG_ID,
          graph_version: META_GRAPH_VERSION,
          oauth_state: state,
          onboarding_mode: whatsappOnboardingMode,
          flow: whatsappOnboardingMode === "coexistence"
            ? "whatsapp_business_app_coexistence"
            : whatsappOnboardingMode === "coexistence_recovery"
              ? "whatsapp_business_app_recovery"
            : "new_cloud_api_number"
        }
      });
      return;
    }
    res.json({ ok: true, authorization_url: authorizationUrl });
  } catch (error) {
    console.error("customer channel connect start error:", error.message);
    channelConnectionErrorResponse(res, error);
  }
});

app.post("/admin/panel/channel-connections/whatsapp/complete", async (req, res) => {
  if (!CHANNEL_CONNECTIONS_V1_VISIBLE || !channelConnectionService) {
    res.status(404).json({ ok: false, error: "channel_connections_disabled" });
    return;
  }
  if (!customerPanelAuthOk(req, "admin")) {
    res.status(401).json({ ok: false, error: "unauthorized" });
    return;
  }
  const auth = dashboardAuth(req);
  if (!await customerChannelConnectionsVisibleForPanelAuth(auth)) {
    res.status(404).json({ ok: false, error: "channel_connections_disabled" });
    return;
  }
  const state = readOAuthState(DASHBOARD_SESSION_SECRET, req.body && req.body.state);
  const tenantId = customerChannelTenantForAuth(auth);
  if (!state || state.channel !== "whatsapp" || !state.whatsapp_attempt_id ||
      state.tenant_id !== tenantId ||
      String(state.actor_id) !== String(auth.user_id || auth.username)) {
    res.status(403).json({ ok: false, error: "invalid_authorization" });
    return;
  }
  try {
    const embeddedSession = Object.assign({}, req.body && req.body.session || {}, {
      onboarding_mode: state.whatsapp_onboarding_mode || "cloud_api"
    });
    const result = await channelConnectionService.completeEmbeddedWhatsApp({
      tenant_id: tenantId,
      actor: auth,
      redirect_uri: state.redirect_uri || channelConnectionCallbackUrlForRequest(req),
      attempt_id: state.whatsapp_attempt_id,
      code: req.body && req.body.code,
      session: embeddedSession
    });
    invalidateChannelRuntimeCache();
    log("info", "whatsapp_customer_activation_result", {
      tenant_id: tenantId,
      status: result.connection && result.connection.status,
      webhook_status: result.connection && result.connection.webhook_status,
      onboarding_mode: embeddedSession.onboarding_mode,
      onboarding_event: cleanRuntimeText(embeddedSession.onboarding_event, 100) || null
    });
    res.json({ ok: true, connection: result.connection });
  } catch (error) {
    console.error("WhatsApp Embedded Signup failed:", error.internalMessage || error.message);
    channelConnectionErrorResponse(res, error);
  }
});

