app.get("/admin/panel/orders-data", async (req, res) => {
  if (!customerPanelAuthOk(req, "viewer")) {
    res.status(401).json({ ok: false, error: "unauthorized" });
    return;
  }
  const auth = dashboardAuth(req);
  const tenantId = customerTenantForAuth(auth);
  let business = customerBusinessForAuth(auth);
  try { business = customerBusinessForAuthAndOnboarding(auth, await loadClientOnboarding(false, tenantId)); }
  catch (_) {}
  if (!customerBusinessHasOrdersModule(business)) {
    res.status(403).json({ ok: false, error: "module_not_contracted" });
    return;
  }
  try {
    const storedOrders = await customerOrderService.list(tenantId, 300);
    let profileTurns = conversationLogs.filter(function (turn) {
      return cleanTenantId(turn.tenantId || turn.tenant_id) === tenantId && isCustomerMetaTurn(turn);
    });
    if (SUPABASE_ENABLED) {
      try {
        const rows = await supabaseFetchLatestToolStates(CUSTOMER_META_TOOL, { tenantId });
        if (rows) profileTurns = rows.map(normalizeTurnRow);
      } catch (profileError) {
        log("warn", "customer_orders_profile_enrichment_failed", {
          tenant_id: tenantId,
          error: String(profileError && profileError.message || profileError || "unknown").slice(0, 180)
        });
      }
    }
    const profiles = customerMetaFromTurns(profileTurns);
    const orders = storedOrders.map(function (order) {
      const customerId = normalizeConversationUserId(order.conversation_id);
      return enrichCustomerOrderContact(order, profiles[customerId]);
    });
    res.json({
      ok: true,
      source: SUPABASE_ENABLED ? "tenant_supabase" : "memory_test_only",
      business: { id: business.id, name: business.company_name || business.name },
      can_manage: !!customerPanelCapabilities(auth.role).manage_orders,
      orders
    });
  } catch (error) {
    console.error("customer orders list error:", error.message);
    res.status(503).json({ ok: false, error: "orders_unavailable" });
  }
});

// Reporte de bug del bot hecho por el cliente desde Conversaciones.
// El tenant sale SIEMPRE de la sesion firmada, nunca del body: si viniera del
// navegador, un cliente podria abrir incidencias a nombre de otro.
app.post("/admin/panel/bug-reports", async (req, res) => {
  if (!customerPanelAuthOk(req, "agent")) {
    res.status(401).json({ ok: false, error: "unauthorized" });
    return;
  }
  if (!botOpsService) {
    res.status(503).json({ ok: false, error: "bot_ops_unavailable", message: "No pudimos registrar el reporte. Intenta de nuevo en unos minutos." });
    return;
  }
  const auth = dashboardAuth(req);
  const tenantId = customerTenantForAuth(auth);
  const body = req.body || {};
  const reason = String(body.reason || "otro").trim().toLowerCase();
  const note = String(body.note || "").trim().slice(0, 1000);
  const allowedReasons = ["respuesta_incorrecta", "no_entendio", "no_respondio", "tono", "otro"];
  if (!allowedReasons.includes(reason)) {
    res.status(400).json({ ok: false, error: "invalid_reason", message: "Elige qué fue lo que pasó." });
    return;
  }
  try {
    const result = await botOpsService.reportIssue({
      tenant_id: tenantId,
      bot_id: String(body.bot_id || auth.assigned_bot_id || "").trim().toLowerCase(),
      channel: String(body.channel || "").trim().toLowerCase(),
      conversation_key: String(body.conversation_id || "").trim().slice(0, 80),
      reason,
      note,
      reported_by: auth.email || auth.username || auth.name || "customer_panel",
      bot_version: BOT_VERSION,
      customer_message: body.customer_message,
      bot_reply: body.bot_reply
    });
    if (!result.ok) {
      res.status(503).json({ ok: false, error: "report_not_stored", message: "No pudimos registrar el reporte. Intenta de nuevo en unos minutos." });
      return;
    }
    res.json({ ok: true, finding_recorded: result.finding_recorded });
  } catch (error) {
    console.error("customer bug report error:", error.message);
    res.status(503).json({ ok: false, error: "report_failed", message: "No pudimos registrar el reporte. Intenta de nuevo en unos minutos." });
  }
});

app.post("/admin/panel/orders/action", async (req, res) => {
  if (!customerPanelAuthOk(req, "agent")) {
    res.status(401).json({ ok: false, error: "unauthorized" });
    return;
  }
  const auth = dashboardAuth(req);
  const tenantId = customerTenantForAuth(auth);
  let business = customerBusinessForAuth(auth);
  try { business = customerBusinessForAuthAndOnboarding(auth, await loadClientOnboarding(false, tenantId)); }
  catch (_) {}
  if (!customerBusinessHasOrdersModule(business)) {
    res.status(403).json({ ok: false, error: "module_not_contracted" });
    return;
  }
  const body = req.body || {};
  try {
    const order = await customerOrderService.action(
      tenantId,
      body.order_id,
      body.action,
      { tracking_number: body.tracking_number, tracking_url: body.tracking_url, shipping: body.shipping },
      auth.email || auth.username || auth.name || "customer_panel"
    );
    if (body.action === "confirm_payment") {
      try {
        await customerNotificationEmailService.scheduleEvent({
          tenant_id: tenantId,
          notification_id: "shipping-pending:" + order.id + ":" + order.revision,
          template: "shipping_pending",
          send_after: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString(),
          payload: {
            action_url: "/admin/panel?tab=orders&order=" + encodeURIComponent(order.id),
            orders: [{
              id: order.id,
              order_number: order.order_number,
              name: order.name,
              item_count: (order.items || []).reduce(function (total, item) { return total + (Number(item.qty) || 1); }, 0),
              wait_days: 1
            }]
          }
        });
      } catch (emailError) {
        log("warn", "customer_notification_shipping_schedule_failed", {
          tenant_id: tenantId,
          order_id: order.id,
          error: String(emailError && emailError.message || emailError || "unknown").slice(0, 180)
        });
      }
    }
    let panelOrder = order;
    try {
      const profile = await loadCustomerMeta(order.conversation_id, tenantId);
      panelOrder = enrichCustomerOrderContact(order, profile);
    } catch (profileError) {
      log("warn", "customer_order_action_profile_enrichment_failed", {
        tenant_id: tenantId,
        order_id: order.id,
        error: String(profileError && profileError.message || profileError || "unknown").slice(0, 180)
      });
    }
    res.json({ ok: true, order: panelOrder });
  } catch (error) {
    const status = error instanceof CustomerOrderError ? error.status : 503;
    res.status(status).json({ ok: false, error: error.code || "order_action_failed", message: error.message });
  }
});

function publicAppointmentSettings(settings, configuration) {
  return {
    version: settings.version,
    revision: settings.revision,
    rules: settings.scheduling_rules,
    scheduling_rules: settings.scheduling_rules,
    exceptions: settings.schedule_exceptions,
    schedule_exceptions: settings.schedule_exceptions,
    reminder_policy: settings.reminder_policy,
    booking_policy: settings.booking_policy,
    default_duration_minutes: settings.booking_policy.default_duration_minutes,
    buffer_minutes: settings.booking_policy.buffer_minutes,
    booking_requirements: settings.booking_requirements,
    appointment_services: settings.appointment_services,
    appointment_service_statuses: (settings.appointment_services || []).map(function (service) {
      const result = validateAppointmentService(service);
      return {
        id: cleanRuntimeText(service && service.id, 100),
        status: result.ok ? "ready" : "draft",
        error: result.ok ? null : result.error
      };
    }),
    availability_rules: settings.availability_rules,
    services: cleanRuntimeText(configuration && configuration.services, 8000),
    minimum_booking_notice: cleanRuntimeText(configuration && configuration.minimum_booking_notice, 1200),
    maximum_booking_window: cleanRuntimeText(configuration && configuration.maximum_booking_window, 1200),
    booking_confirmation_mode: cleanRuntimeText(configuration && configuration.booking_confirmation_mode, 1200),
    cancellation_policy: cleanRuntimeText(configuration && configuration.cancellation_policy, 5000),
    no_show_policy: cleanRuntimeText(configuration && configuration.no_show_policy, 3000),
    booking_payment_details: cleanRuntimeText(configuration && configuration.booking_payment_details, 3000),
    timezone: cleanRuntimeText(configuration && configuration.time_zone, 120) || "America/Bogota",
    sync_status: cleanRuntimeText(configuration && configuration.settings_sync_status, 80) || "applied",
    synced_at: configuration && configuration.settings_synced_at || null,
    last_sync_error: cleanRuntimeText(configuration && configuration.settings_last_error, 500) || "",
    updated_at: settings.updated_at,
    updated_by: settings.updated_by
  };
}

// Super Admin needs an authoritative receipt for what the Customer Panel
// actually persisted.  This is intentionally derived from the same tenant
// onboarding record consumed by Tempo/Atlas: it creates neither a parallel
// configuration store nor a browser-trusted tenant context.
function appointmentConfigurationVerification(tenantId, onboarding) {
  const cleanTenant = cleanTenantId(tenantId);
  const settings = appointmentSettingsFromOnboarding(onboarding);
  const configuration = onboarding && onboarding.appointment_configuration || {};
  const services = Array.isArray(settings.appointment_services) ? settings.appointment_services : [];
  const botContext = compileAppointmentServices(services);
  const receipt = {
    tenant_id: cleanTenant,
    revision: Number(settings.revision) || 0,
    // The onboarding record timestamp is persisted. normalizeAppointmentSettings
    // may synthesize a timestamp for legacy records, so it must not lead the
    // receipt or the same database row would produce a different fingerprint
    // on every read.
    updated_at: onboarding && (onboarding.last_updated_at || onboarding.updated_at) || settings.updated_at || null,
    updated_by: cleanRuntimeText(onboarding && onboarding.updated_by || settings.updated_by, 160) || null,
    persistence: SUPABASE_ENABLED ? "supabase" : "memory_test_only",
    source: "client_onboarding_record",
    sync_status: cleanRuntimeText(configuration.settings_sync_status, 80) || "applied",
    synced_at: configuration.settings_synced_at || null,
    bot_context_ready: !!botContext,
    service_count: services.length,
    services: services.map(function (service) {
      const deposit = service && service.deposit || {};
      return {
        id: cleanRuntimeText(service && service.id, 100),
        name: cleanRuntimeText(service && service.name, 240),
        description: cleanRuntimeText(service && service.description, 1600),
        active: service && service.active !== false,
        duration_minutes: Number(service && service.duration_minutes) || 0,
        price_cop: Number(service && service.price_cop) || 0,
        modality: cleanRuntimeText(service && service.modality, 40),
        deposit_required: !!deposit.required,
        payment_methods: (Array.isArray(service && service.payment_methods) ? service.payment_methods : []).filter(function (method) {
          return method && method.active !== false;
        }).map(function (method) {
          // Do not return payment instructions or account details in an audit
          // receipt. Their presence is verifiable without re-exposing them.
          return {
            id: cleanRuntimeText(method.id || method.type, 100),
            label: cleanRuntimeText(method.label || method.type, 160),
            instructions_configured: !!cleanRuntimeText(method.instructions, 2000)
          };
        })
      };
    })
  };
  receipt.fingerprint = crypto.createHash("sha256").update(JSON.stringify({
    tenant_id: receipt.tenant_id,
    revision: receipt.revision,
    updated_at: receipt.updated_at,
    services: receipt.services,
    bot_context: botContext
  })).digest("hex").slice(0, 16);
  receipt.verified_at = new Date().toISOString();
  return receipt;
}

async function verifyPersistedAppointmentSettings(tenantId, expectedRecord) {
  const expected = appointmentConfigurationVerification(tenantId, expectedRecord);
  if (!SUPABASE_ENABLED) {
    return { record: expectedRecord, verification: expected };
  }
  const rows = await supabaseFetchUserToolRecent(
    clientOnboardingRecordId(tenantId),
    CLIENT_ONBOARDING_TOOL,
    10,
    { tenantId, strict: true }
  );
  const persisted = (rows || []).map(normalizeTurnRow).map(function (turn) {
    return parseClientOnboardingTurn(turn, tenantId);
  }).filter(Boolean).find(function (record) {
    const receipt = appointmentConfigurationVerification(tenantId, record);
    return receipt.revision === expected.revision && receipt.fingerprint === expected.fingerprint;
  });
  if (!persisted) {
    throw new AppointmentOperationsError("appointment_settings_persistence_unverified", 503, {
      expected_revision: expected.revision,
      expected_fingerprint: expected.fingerprint
    });
  }
  clientOnboardingCacheByTenant.set(tenantId, {
    loaded_at: Date.now(),
    record: persisted
  });
  return {
    record: persisted,
    verification: appointmentConfigurationVerification(tenantId, persisted)
  };
}

function appointmentReminderMetrics(snapshot) {
  const items = snapshot && snapshot.items || [];
  const byAppointment = new Map();
  items.forEach(function (row) {
    const appointmentId = cleanRuntimeText(row && row.appointment_id, 160);
    if (!appointmentId) return;
    if (!byAppointment.has(appointmentId)) byAppointment.set(appointmentId, []);
    byAppointment.get(appointmentId).push(row);
  });
  const resolved = Array.from(byAppointment.values()).filter(function (rows) {
    return rows.some(function (row) { return ["sent", "delivered", "read", "confirmed", "no_response"].includes(row.status); });
  });
  const confirmed = resolved.filter(function (rows) {
    return rows.some(function (row) { return row.status === "confirmed"; });
  }).length;
  const avoided = Array.from(byAppointment.values()).filter(function (rows) {
    return rows.some(function (row) { return row && row.metadata && row.metadata.avoided_absence === true; });
  }).length;
  return {
    confirmation_rate: resolved.length ? Math.round(confirmed / resolved.length * 100) : 0,
    avoided_absences: avoided,
    sent_reminders: snapshot && snapshot.sent_count || 0
  };
}

function appointmentDateInTimezone(value, timezone) {
  const parsed = new Date(value || "");
  if (!Number.isFinite(parsed.getTime())) return "";
  try {
    const parts = new Intl.DateTimeFormat("en-CA", {
      timeZone: cleanRuntimeText(timezone, 100) || "America/Bogota",
      year: "numeric",
      month: "2-digit",
      day: "2-digit"
    }).formatToParts(parsed).reduce(function (result, part) {
      result[part.type] = part.value;
      return result;
    }, {});
    return [parts.year, parts.month, parts.day].join("-");
  } catch (_) {
    return parsed.toISOString().slice(0, 10);
  }
}

async function createAppointmentExceptionWorkflows(tenantId, settings, actor) {
  const actionable = new Map((settings.schedule_exceptions || []).filter(function (row) {
    return row.active !== false && ["reschedule", "partial"].includes(row.mode) && row.date;
  }).map(function (row) { return [row.date, row]; }));
  if (!actionable.size) return [];
  await hydrateAppointmentsForTenant(tenantId);
  const affected = appointmentRegistry.list(tenantId).filter(function (appointment) {
    if (!["booked", "rescheduled"].includes(appointment.status)) return false;
    const date = appointmentDateInTimezone(appointment.starts_at, settings.timezone);
    if (!actionable.has(date)) return false;
    const exception = actionable.get(date);
    return exception.mode === "reschedule" || !!evaluateScheduleException(
      settings,
      appointment.starts_at,
      appointment.duration_minutes,
      settings.timezone
    );
  });
  const updated = [];
  for (const appointment of affected) {
    const exception = actionable.get(appointmentDateInTimezone(appointment.starts_at, settings.timezone));
    const action = exception && exception.mode === "partial" && exception.outside_action === "cancel"
      ? "cancel"
      : "reprogram";
    const row = await appointmentRegistry.applyPanelAction(tenantId, appointment.appointment_id, action, {
      actor,
      reason: "Excepción de agenda creada desde el Customer Panel",
      message: action === "cancel"
        ? "Cita cancelada porque quedó fuera del horario especial configurado."
        : "Esta cita requiere acordar una nueva fecha con el cliente.",
      persist: false
    });
    await persistAppointment(row);
    await syncAppointmentReminderSchedule(tenantId, row);
    if (row.customer_conversation_id) {
      try {
        await customerNotificationService.createHandoff({
          id: "appointment-exception:" + row.appointment_id + ":" + appointmentDateInTimezone(row.starts_at, settings.timezone),
          tenant_id: tenantId,
          conversation_id: row.customer_conversation_id,
          channel: row.channel === "whatsapp" ? "whatsapp" : conversationChannel(row.customer_conversation_id),
          customer_label: row.customer_name || "Un cliente",
          reason: "appointment_schedule_exception",
          title: action === "cancel" ? "Una cita fue cancelada" : "Una cita necesita nueva fecha",
          message: action === "cancel"
            ? "La cita quedó fuera del horario especial y fue cancelada según tu regla."
            : "La cita quedó fuera del horario especial. Abre la conversación para acordar una nueva fecha."
        });
      } catch (error) {
        log("warn", "appointment_exception_notification_failed", {
          tenant_id: tenantId,
          appointment_id: row.appointment_id,
          error: cleanRuntimeText(error && error.message, 240)
        });
      }
    }
    updated.push(row.appointment_id);
  }
  return updated;
}

async function appointmentSettingsRecordForTenant(tenantId) {
  const onboarding = await loadClientOnboarding(false, tenantId);
  const settings = appointmentSettingsFromOnboarding(onboarding);
  return { onboarding, settings };
}

async function saveAppointmentSettingsForTenant(tenantId, input, auth) {
  const current = await appointmentSettingsRecordForTenant(tenantId);
  const body = input && typeof input === "object" ? input : {};
  const patch = body.settings && typeof body.settings === "object" ? body.settings : body;
  const expectedRevision = body.revision != null ? body.revision : patch.revision;
  const actor = auth && (auth.email || auth.username || auth.name) || "customer_panel";
  const settingsPatch = {};
  if (Object.prototype.hasOwnProperty.call(patch, "rules") || Object.prototype.hasOwnProperty.call(patch, "scheduling_rules")) {
    settingsPatch.scheduling_rules = Object.prototype.hasOwnProperty.call(patch, "rules") ? patch.rules : patch.scheduling_rules;
  }
  if (Object.prototype.hasOwnProperty.call(patch, "exceptions") || Object.prototype.hasOwnProperty.call(patch, "schedule_exceptions")) {
    settingsPatch.schedule_exceptions = Object.prototype.hasOwnProperty.call(patch, "exceptions") ? patch.exceptions : patch.schedule_exceptions;
  }
  if (Object.prototype.hasOwnProperty.call(patch, "reminder_policy")) settingsPatch.reminder_policy = patch.reminder_policy;
  if (Object.prototype.hasOwnProperty.call(patch, "booking_requirements")) settingsPatch.booking_requirements = patch.booking_requirements;
  if (Object.prototype.hasOwnProperty.call(patch, "appointment_services")) settingsPatch.appointment_services = patch.appointment_services;
  if (Object.prototype.hasOwnProperty.call(patch, "booking_policy") ||
      Object.prototype.hasOwnProperty.call(patch, "default_duration_minutes") ||
      Object.prototype.hasOwnProperty.call(patch, "buffer_minutes")) {
    settingsPatch.booking_policy = Object.assign({}, patch.booking_policy || {});
    if (Object.prototype.hasOwnProperty.call(patch, "default_duration_minutes")) {
      settingsPatch.booking_policy.default_duration_minutes = patch.default_duration_minutes;
    }
    if (Object.prototype.hasOwnProperty.call(patch, "buffer_minutes")) {
      settingsPatch.booking_policy.buffer_minutes = patch.buffer_minutes;
    }
  }
  const updated = updateAppointmentSettings(current.settings, settingsPatch, { expectedRevision, actor });
  const previous = current.onboarding;
  const previousAppointmentSetup = previous.answers && previous.answers.appointment_setup || {};
  const previousConfiguration = previous.appointment_configuration || {};
  function appointmentContentValue(field, max) {
    if (Object.prototype.hasOwnProperty.call(patch, field)) return cleanRuntimeText(patch[field], max);
    return cleanRuntimeText(previousConfiguration[field] || previousAppointmentSetup[field], max);
  }
  const appointmentContent = {
    services: appointmentContentValue("services", 8000),
    minimum_booking_notice: appointmentContentValue("minimum_booking_notice", 1200),
    maximum_booking_window: appointmentContentValue("maximum_booking_window", 1200),
    booking_confirmation_mode: appointmentContentValue("booking_confirmation_mode", 1200),
    cancellation_policy: appointmentContentValue("cancellation_policy", 5000),
    no_show_policy: appointmentContentValue("no_show_policy", 3000),
    booking_payment_details: appointmentContentValue("booking_payment_details", 3000)
  };
  const answers = JSON.parse(JSON.stringify(previous.answers || {}));
  answers.appointment_setup = Object.assign({}, answers.appointment_setup || {}, {
    availability_rules: updated.availability_rules,
    scheduling_rules: updated.scheduling_rules,
    schedule_exceptions: updated.schedule_exceptions,
    reminder_policy: updated.reminder_policy,
    booking_policy: updated.booking_policy,
    default_duration_minutes: updated.booking_policy.default_duration_minutes,
    buffer_minutes: updated.booking_policy.buffer_minutes,
    booking_requirements: updated.booking_requirements,
    appointment_services: updated.appointment_services,
    required_booking_fields: updated.required_booking_fields,
    revision: updated.revision,
    reminder_channel: updated.reminder_policy.channel || "none",
    reminder_timing: updated.reminder_policy.offsets_minutes
  }, appointmentContent);
  let configuration = normalizeAppointmentConfiguration(Object.assign({}, previous.appointment_configuration || {}, {
    availability_rules: updated.availability_rules,
    scheduling_rules: updated.scheduling_rules,
    schedule_exceptions: updated.schedule_exceptions,
    reminder_policy: updated.reminder_policy,
    booking_policy: updated.booking_policy,
    default_duration_minutes: updated.booking_policy.default_duration_minutes,
    buffer_minutes: updated.booking_policy.buffer_minutes,
    booking_requirements: updated.booking_requirements,
    appointment_services: updated.appointment_services,
    required_booking_fields: updated.required_booking_fields,
    revision: updated.revision,
    reminder_channel: updated.reminder_policy.channel || "none",
    reminder_timing: updated.reminder_policy.offsets_minutes.map(function (minutes) { return Math.round(minutes / 60) + " h antes"; }).join(" y "),
    settings_sync_status: "pending_external_apply",
    settings_synced_at: "",
    settings_last_error: ""
  }, appointmentContent), {
    actor,
    lifecycle: previous.appointment_configuration && previous.appointment_configuration.lifecycle || "draft"
  });
  if (configuration.external_agent_id && ELEVENLABS_APPOINTMENT_AGENT_WRITE_ENABLED) {
    try {
      const applied = await applyElevenLabsAppointmentAgent({
        tenant_id: tenantId,
        answers,
        appointment_configuration: configuration
      }, tenantId, {
        apiKey: ELEVENLABS_API_KEY,
        agentId: configuration.external_agent_id,
        agentTenantMap: ELEVENLABS_AGENT_TENANT_MAP,
        toolSecret: ELEVENLABS_APPOINTMENT_TOOL_SECRET,
        toolBaseUrl: ELEVENLABS_APPOINTMENT_TOOL_BASE_URL,
        writeEnabled: true,
        httpClient: axios
      });
      configuration = normalizeAppointmentConfiguration(Object.assign(
        {},
        markAppointmentConfigurationElevenLabsApplied(configuration, applied, actor),
        { settings_sync_status: "applied", settings_synced_at: new Date().toISOString(), settings_last_error: "" }
      ), { actor, lifecycle: configuration.lifecycle });
    } catch (error) {
      configuration = normalizeAppointmentConfiguration(Object.assign({}, configuration, {
        settings_sync_status: "failed",
        settings_last_error: cleanRuntimeText(error && error.message, 500)
      }), { actor, lifecycle: configuration.lifecycle });
    }
  }
  const record = createOnboardingRecord(answers, {
    tenant_id: tenantId,
    status: previous.status || "completed",
    updated_by: actor,
    previous,
    customer_service_configuration: previous.customer_service_configuration || null,
    appointment_configuration: configuration,
    configuration_lifecycle: previous.customer_service_configuration && previous.customer_service_configuration.lifecycle,
    appointment_configuration_lifecycle: configuration.lifecycle,
    review_status: setupReviewSummary(previous).status,
    review_actor: actor,
    review_note: setupReviewSummary(previous).note,
    requested_changes: setupReviewSummary(previous).requested_changes,
    review_event: { action: "appointment_settings_updated", note: "Servicios y reglas de citas actualizados desde Customer Panel." }
  });
  await appendClientOnboardingRecord(record, tenantId);
  const persisted = await verifyPersistedAppointmentSettings(tenantId, record);
  const savedRecord = persisted.record;
  const savedSettings = appointmentSettingsFromOnboarding(savedRecord);
  const affectedAppointments = await createAppointmentExceptionWorkflows(tenantId, Object.assign({}, savedSettings, {
    timezone: cleanRuntimeText(savedRecord.appointment_configuration && savedRecord.appointment_configuration.time_zone, 120) || "America/Bogota"
  }), actor);
  return {
    record: savedRecord,
    settings: savedSettings,
    affectedAppointments,
    verification: persisted.verification,
    persistenceVerified: true
  };
}

