// This endpoint is deliberately the only transition to `received`.  It is
// tenant-scoped from the signed panel session and never accepts a customer or
// bot assertion as proof of payment.
app.post("/admin/panel/appointments/:appointmentId/deposit/received", async (req, res) => {
  if (!customerPanelAuthOk(req, "agent")) return res.status(401).json({ ok: false, error: "unauthorized" });
  const auth = dashboardAuth(req);
  const tenantId = customerTenantForAuth(auth);
  const appointmentId = cleanRuntimeText(req.params && req.params.appointmentId, 160);
  const method = cleanRuntimeText(req.body && req.body.method, 40).toLowerCase().replace(/[\s-]+/g, "_");
  const note = cleanRuntimeText(req.body && req.body.note, 1000);
  if (!appointmentId) return res.status(422).json({ ok: false, error: "appointment_id_required" });
  if (!["nequi", "transfer", "payment_link", "cash", "other", "bank_transfer"].includes(method)) {
    return res.status(422).json({ ok: false, error: "valid_deposit_method_required" });
  }
  await hydrateAppointmentsForTenant(tenantId);
  const current = appointmentRegistry.get(tenantId, appointmentId);
  if (!current) return res.status(404).json({ ok: false, error: "appointment_not_found" });
  const deposit = current.deposit || { status: current.deposit_status || "not_required", amount: 0, currency: "COP" };
  if (deposit.status === "not_required") return res.status(422).json({ ok: false, error: "appointment_has_no_deposit" });
  // Idempotent retries are safe: they neither alter another tenant nor send a
  // duplicate customer confirmation.
  if (deposit.status === "received") return res.json({ ok: true, idempotent: true, appointment: current });
  const actor = auth.name || auth.email || auth.username || "customer_panel";
  const now = new Date().toISOString();
  try {
    let updated = await appointmentRegistry.upsert(Object.assign({}, current, {
      deposit: Object.assign({}, deposit, {
        status: "received",
        method,
        received_at: now,
        received_by: actor,
        note
      }),
      deposit_status: "received",
      deposit_reminder_state: "stopped",
      deposit_audit: (Array.isArray(current.deposit_audit) ? current.deposit_audit : []).concat([{
        at: now,
        action: "owner_marked_deposit_received",
        actor,
        method
      }]).slice(-30),
      updated_at: now
    }), false);
    // A deposit-blocked appointment is released only after this human action.
    if (updated.deposit && updated.deposit.blocks_confirmation && updated.status === "requested") {
      updated = await appointmentRegistry.applyPanelAction(tenantId, appointmentId, "confirm", { actor, persist: false });
      updated = await applyAppointmentCalendarEffect(updated, "sync", actor);
    }
    await persistAppointment(updated);
    await syncAppointmentReminderSchedule(tenantId, updated);
    let confirmation = null;
    if (updated.status === "booked" && APPOINTMENT_CONFIRMATIONS_ENABLED) {
      confirmation = await appointmentConfirmationService.send(updated);
      if (confirmation && confirmation.appointment) updated = confirmation.appointment;
      await persistAppointment(updated);
    }
    log("info", "appointment_deposit_received_by_owner", {
      tenant_id: cleanTenantId(tenantId),
      appointment_id_suffix: appointmentId.slice(-12),
      actor: cleanRuntimeText(actor, 120),
      method
    });
    res.json({ ok: true, appointment: updated, customer_confirmation_status: confirmation && confirmation.delivery && confirmation.delivery.status || null });
  } catch (error) {
    res.status(422).json({ ok: false, error: String(error && (error.code || error.message) || "deposit_receive_failed") });
  }
});

app.post("/admin/panel/appointments/action", async (req, res) => {
  if (!customerPanelAuthOk(req, "agent")) {
    res.status(401).json({ ok: false, error: "unauthorized" });
    return;
  }
  const auth = dashboardAuth(req);
  const tenantId = customerTenantForAuth(auth);
  let business = customerBusinessForAuth(auth);
  try {
    business = customerBusinessForAuthAndOnboarding(auth, await loadClientOnboarding(false, tenantId));
  } catch (_) {}
  if (!customerBusinessHasAppointmentModule(business)) {
    res.status(403).json({ ok: false, error: "module_not_contracted" });
    return;
  }
  const body = req.body || {};
  const action = String(body.action || "").trim().toLowerCase().replace(/[\s-]+/g, "_");
  const rawIds = Array.isArray(body.appointment_ids)
    ? body.appointment_ids
    : [body.appointment_id || body.conversation_id];
  const appointmentIds = Array.from(new Set(rawIds.map(function (value) {
    return String(value || "").trim().slice(0, 160);
  }).filter(Boolean))).slice(0, 100);
  if (!["confirm", "cancel", "reprogram"].includes(action) || appointmentIds.length < 1) {
    res.status(400).json({ ok: false, error: "invalid_appointment_action" });
    return;
  }
  await hydrateAppointmentsForTenant(tenantId);
  const existingIds = new Set(appointmentRegistry.list(tenantId).map(function (row) { return row.appointment_id; }));
  const missingId = appointmentIds.find(function (appointmentId) { return !existingIds.has(appointmentId); });
  if (missingId) {
    res.status(404).json({ ok: false, error: "appointment_not_found" });
    return;
  }
  const actor = auth.name || auth.email || auth.username || "customer_panel";
  const updated = [];
  try {
    for (const appointmentId of appointmentIds) {
      const current = appointmentRegistry.get(tenantId, appointmentId);
      if (action === "confirm" && current && current.deposit && current.deposit.blocks_confirmation && current.deposit.status !== "received") {
        return res.status(422).json({ ok: false, error: "deposit_pending_blocks_confirmation", appointment_id: appointmentId });
      }
      const row = await appointmentRegistry.applyPanelAction(tenantId, appointmentId, action, {
        actor,
        reason: body.reason,
        message: body.message,
        persist: false
      });
      const calendarRow = action === "confirm" && row.starts_at
        ? await applyAppointmentCalendarEffect(row, "sync", actor)
        : action === "cancel"
          ? await applyAppointmentCalendarEffect(row, "cancel", actor)
          : row;
      await persistAppointment(calendarRow);
      await syncAppointmentReminderSchedule(tenantId, calendarRow);
      updated.push(calendarRow);
    }
    const snapshot = appointmentRegistry.snapshot(tenantId);
    const onboarding = await loadClientOnboarding(false, tenantId);
    const settings = appointmentSettingsFromOnboarding(onboarding);
    const reminders = await refreshAppointmentRemindersForTenant(tenantId, settings, snapshot.appointments);
    const reminderData = reminderSnapshot(reminders, { tenantId });
    const responsePayload = customerAppointmentSnapshot(snapshot, business);
    responsePayload.metrics = Object.assign({}, responsePayload.metrics, appointmentReminderMetrics(reminderData));
    res.json(Object.assign(responsePayload, {
      ok: true,
      action,
      updated_count: updated.length,
      updated_appointments: updated.map(function (row) { return row.appointment_id; }),
      settings: publicAppointmentSettings(settings, onboarding.appointment_configuration),
      reminders: reminderData.items,
      reminder_metrics: reminderData,
      capabilities: {
        manage_appointments: true,
        manage_settings: customerPanelAuthOk(req, "admin"),
        manage_reminders: true,
        send_reminders: APPOINTMENT_REMINDER_SENDS_ENABLED
      }
    }));
  } catch (error) {
    const status = error.message === "appointment_not_found" ? 404 : 400;
    res.status(status).json({ ok: false, error: error.message });
  }
});

app.post("/admin/panel/appointment-reminders/:reminderId/action", async (req, res) => {
  if (!customerPanelAuthOk(req, "agent")) return res.status(401).json({ ok: false, error: "unauthorized" });
  const auth = dashboardAuth(req);
  const tenantId = customerTenantForAuth(auth);
  const business = customerBusinessForAuthAndOnboarding(auth, await loadClientOnboarding(false, tenantId));
  if (!customerBusinessHasAppointmentModule(business)) return res.status(403).json({ ok: false, error: "module_not_contracted" });
  try {
    const rows = await loadAppointmentRemindersForTenant(tenantId);
    const reminder = rows.find(function (row) { return String(row.id) === String(req.params.reminderId); });
    if (!reminder) throw new AppointmentOperationsError("appointment_reminder_not_found", 404);
    const actor = auth.email || auth.username || auth.name || "customer_panel";
    let updated = applyReminderAction(reminder, req.body && req.body.action, { tenantId, actor });
    updated = Object.assign({}, reminder, updated, { attempts: Number(reminder.attempts) || 0 });
    await persistAppointmentReminders([updated]);
    if (["send_now", "retry"].includes(String(req.body && req.body.action || ""))) {
      updated = await sendAppointmentReminderRecord(updated, actor);
    }
    const current = await loadAppointmentRemindersForTenant(tenantId);
    const snapshot = reminderSnapshot(current, { tenantId });
    res.json({ ok: true, reminder: updated, reminders: snapshot.items, reminder_metrics: snapshot });
  } catch (error) {
    const status = error instanceof AppointmentOperationsError ? error.status : Number(error && error.status) || 502;
    res.status(status).json({
      ok: false,
      error: error.code || cleanRuntimeText(error && error.message, 120) || "appointment_reminder_action_failed"
    });
  }
});

