app.get("/admin/panel", async (req, res) => {
  const auth = dashboardAuth(req);
  const requestedTab = ["summary", "conversations", "human", "orders", "appointments", "plan", "channels", "setup", "notifications", "retargeting", "tests"].includes(req.query.tab) ? req.query.tab : "summary";
  const loginTarget = "/admin/panel?tab=" + requestedTab;
  if (!auth.ok) {
    if (CUSTOMER_ACCESS_V2_ENABLED) res.redirect("/admin/login?next=" + encodeURIComponent(loginTarget));
    else renderAdminLogin(res, "/admin/panel?tab=" + requestedTab);
    return;
  }
  const panelTenantId = customerTenantForAuth(auth);
  if (!panelTenantId || !canAccessTenant(auth, panelTenantId)) {
    clearDashboardSessionCookie(req, res);
    res.redirect("/admin/login?next=" + encodeURIComponent(loginTarget));
    return;
  }
  if (auth.method === "key") {
    setDashboardSessionCookie(req, res, auth);
  }
  let customerSetupCompleted = false;
  let paymentGateRequired = false;
  let panelBusinessContext = auth.version === 2 ? customerBusinessForAuth(auth) : null;
  if (auth.version === 2) {
    try {
      const onboarding = await loadClientOnboarding(false, panelTenantId);
      panelBusinessContext = customerBusinessForAuthAndOnboarding(auth, onboarding);
      if (!onboarding.setup_completed) {
        res.redirect("/admin/client-onboarding");
        return;
      }
      if (PAYMENTS_V1_ENABLED && paymentService) {
        const billing = await paymentService.tenantBilling(panelTenantId);
        paymentGateRequired = !billingMakesCustomer(billing);
      }
      customerSetupCompleted = true;
    } catch (error) {
      console.error("customer setup gate error:", error.message);
      res.status(503).send("No pudimos comprobar la configuración de tu empresa. Intenta nuevamente.");
      return;
    }
  }
  const capabilities = customerPanelCapabilities(auth.role);
  const channelConnectionsVisibleForCustomer = auth.version === 2
    ? customerChannelConnectionsVisibleForBusiness(panelBusinessContext)
    : customerChannelConnectionsVisibleForAuth(auth);
  let initialTab = ["summary", "conversations", "human", "orders", "appointments", "plan", "channels", "setup", "notifications", "retargeting", "tests"].includes(req.query.tab) ? req.query.tab : "summary";
  if (paymentGateRequired) initialTab = "plan";
  if (initialTab === "channels" && !channelConnectionsVisibleForCustomer) initialTab = "setup";
  if (initialTab === "orders" && !customerBusinessHasOrdersModule(panelBusinessContext)) initialTab = panelBusinessContext && customerBusinessHasAppointmentModule(panelBusinessContext) ? "appointments" : "summary";
  if (initialTab === "tests" && !capabilities.run_tests) {
    initialTab = "plan";
  }
  renderCustomerPanel(res, {
    auth,
    capabilities,
    initialTab,
    initialConversation: normalizeConversationUserId(req.query.conversation),
    initialOrder: String(req.query.order || "").trim().slice(0, 120),
    initialAppointment: String(req.query.appointment || "").trim().slice(0, 160),
    tenantContext: panelBusinessContext,
    customerSetupCompleted,
    paymentsV1Enabled: PAYMENTS_V1_ENABLED,
    paymentGateRequired,
    channelConnectionsV1Enabled: channelConnectionsVisibleForCustomer,
    ordersV1Enabled: customerBusinessHasOrdersModule(panelBusinessContext),
    ordersPath: "/admin/panel/orders-data",
    setupPath: auth.version === 2 ? null : undefined,
    healthPath: auth.version === 2 ? null : undefined,
    pwaEnabled: PWA_V1_ENABLED,
    botVersion: BOT_VERSION
  });
});

app.get("/admin/panel-demo", (req, res) => {
  const auth = { username: "demo", name: "Comercio piloto", role: "admin", method: "demo" };
  const capabilities = customerPanelCapabilities("admin");
  capabilities.manage_notes_tags = false;
  const initialTab = ["summary", "conversations", "human", "orders", "appointments", "plan", "channels", "setup", "notifications", "retargeting"].includes(req.query.tab) ? req.query.tab : "summary";
  const requestedDemoPlan = String(req.query.plan || "").trim().toLowerCase();
  // The appointment review link historically used only ?tab=appointments.
  // Without a plan it silently rendered Aura and redirected to Resumen, which
  // made a successful appointment release look unchanged. Keep explicit plan
  // choices authoritative and infer Tempo only for this appointment entrypoint.
  const demoPlan = requestedDemoPlan || (initialTab === "appointments" ? "tempo" : "");
  const appointmentDemo = demoPlan === "tempo" || demoPlan === "atlas";
  const supportDemo = demoPlan !== "tempo";
  const planId = demoPlan === "tempo" ? "nextfor-tempo" : demoPlan === "atlas" ? "nextfor-atlas" : "nextfor-aura";
  const planName = demoPlan === "tempo" ? "Nextfor Tempo" : demoPlan === "atlas" ? "Nextfor Atlas" : "Nextfor Aura";
  renderCustomerPanel(res, {
    auth,
    capabilities,
    demoMode: true,
    initialTab,
    initialOrder: String(req.query.order || "").trim().slice(0, 120),
    initialAppointment: String(req.query.appointment || "").trim().slice(0, 160),
    tenantContext: {
      id: "nextfor-" + (demoPlan || "aura") + "-demo",
      company_name: "Comercio piloto",
      plan_id: planId,
      plan_name: planName,
      assigned_bot_id: demoPlan === "atlas" ? "both" : appointmentDemo ? "agendamiento" : "customer-service",
      assigned_bot_name: demoPlan === "atlas" ? "Atención al cliente + Agendamiento" : appointmentDemo ? "Agendamiento de citas" : "Atención al cliente",
      support: supportDemo,
      appointments: appointmentDemo
    },
    customerSetupCompleted: true,
    dataPath: "/admin/panel/demo-data",
    appointmentsPath: "/admin/panel/demo-appointments-data",
    setupPath: "/admin/panel/demo-setup",
    personalityPath: "/admin/panel/demo-bot-personality",
    retargetingPath: "/admin/panel/demo-retargeting",
    healthPath: null,
    loginPath: null,
    channelConnectionsV1Enabled: true,
    channelConnectionsDemo: {
      ok: true,
      meta_authorization_available: { whatsapp: true, whatsapp_coexistence: true, instagram: true, messenger: true },
      channels: [
        {
          id: "whatsapp",
          channel: "whatsapp",
          name: "WhatsApp",
          description: "Recomendado. Aquí es donde tu Nextfor empezará a atender primero.",
          status: "not_connected",
          connect_available: true
        },
        {
          id: "instagram",
          channel: "instagram",
          name: "Instagram",
          description: "Opcional. Súmalo si también recibes clientes por mensajes de Instagram.",
          status: "not_connected",
          connect_available: true
        },
        {
          id: "messenger",
          channel: "messenger",
          name: "Facebook Messenger",
          description: "Opcional. Súmalo si tus clientes también te escriben por Facebook.",
          status: "not_connected",
          connect_available: true
        }
      ]
    },
    // La PWA en el demo es opt-in por query (?pwa=1): permite probar instalacion,
    // iconos, standalone y offline SIN credenciales, sin cambiar el demo para
    // nadie que no ponga el parametro. La bandera global sigue mandando en el
    // panel autenticado real.
    pwaEnabled: PWA_V1_ENABLED || req.query.pwa === "1",
    botVersion: BOT_VERSION
  });
});

